/* Atelier Yumi. The character comes untouched from yumi.js (yumi(), Blob, setScene, playPose, RIMS, SCENES).
   Six interface languages; each one has its own navigation, buttons, gestures and flow, on the Mac island and on iPhone.
   All figures and names shown are fictive. */

/* ================= small helpers ================= */
const I={cal:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 10h18M8 3v4M16 3v4"/>',term:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M7 10l3 2-3 2M12 15h5"/>',focus:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>',git:'<circle cx="6" cy="6" r="2.4"/><circle cx="6" cy="18" r="2.4"/><circle cx="18" cy="10" r="2.4"/><path d="M6 8.4v7.2M18 12.4c0 3-4 3-10 4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M4 7l8 6 8-6"/>',music:'<path d="M9 18V6l11-2v12"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="17.5" cy="16" r="2.5"/>',note:'<path d="M5 3h10l4 4v14H5z"/><path d="M9 11h6M9 15h6"/>',notion:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8v8l6-8v8"/>',screen:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.4 1.4M17.6 17.6L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/>',chat:'<path d="M4 5h16v11H9l-5 4z"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1.5"/><rect x="14" y="4" width="6" height="6" rx="1.5"/><rect x="4" y="14" width="6" height="6" rx="1.5"/><rect x="14" y="14" width="6" height="6" rx="1.5"/>',x:'<path d="M6 6l12 12M18 6L6 18"/>',ok:'<path d="M5 12.5l4.5 4.5L19 7.5"/>',stop:'<rect x="7" y="7" width="10" height="10" rx="2"/>',play:'<path d="M8 5l11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',next:'<path d="M6 5l9 7-9 7zM18 5v14"/>',prev:'<path d="M18 5l-9 7 9 7zM6 5v14"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',left:'<path d="M15 6l-6 6 6 6"/>',right:'<path d="M9 6l6 6-6 6"/>',down:'<path d="M6 9l6 6 6-6"/>',mic:'<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0014 0M12 18v3"/>',bell:'<path d="M6 16V11a6 6 0 0112 0v5l2 2H4zM10 20a2 2 0 004 0"/>',bolt:'<path d="M13 3L5 13h6l-1 8 8-10h-6z"/>',phone:'<rect x="7" y="2" width="10" height="20" rx="2.5"/><path d="M11 18h2"/>',laptop:'<rect x="4" y="5" width="16" height="11" rx="1.5"/><path d="M2 19h20"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="6"/><path d="M20 20l-4.5-4.5"/>',more:'<circle cx="5" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="19" cy="12" r="1.3"/>',mem:'<path d="M12 3a6 6 0 00-6 6c0 3 2 4 2 7h8c0-3 2-4 2-7a6 6 0 00-6-6zM9 20h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c1-4 4-6 8-6s7 2 8 6"/>',qr:'<rect x="4" y="4" width="6" height="6"/><rect x="14" y="4" width="6" height="6"/><rect x="4" y="14" width="6" height="6"/><path d="M14 14h2v2h-2zM18 18h2v2h-2zM14 18h2M18 14h2"/>',inbox:'<path d="M3 13l3-8h12l3 8v6H3z"/><path d="M3 13h5l1 2h6l1-2h5"/>',file:'<path d="M6 3h8l4 4v14H6z"/>'};
const ic=(n,s=16,c="currentColor",w=1.9)=>`<svg class="ico" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round">${I[n]||""}</svg>`;
/* Yumi placeholder: mounted with the real yumi() + Blob after render. mood, rim (RIMS key), scene (SCENES key), pose (POSE_FX key) */
const Y=(s,m="neutre",r="calm",sc="",p="")=>`<span class="ys" style="display:inline-block;width:${s}px;height:${s*.84}px;flex:none" data-s="${s}" data-m="${m}" data-r="${r}" data-sc="${sc}" data-p="${p}"></span>`;
const eb=(t,c)=>`<div class="eb" style="color:${c||"var(--imut)"}">${t}</div>`;
const chk=(s,c="#30D158")=>`<svg class="chk" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="11" fill="${c}22"/><path d="M6.5 12.5l3.8 3.8L17.5 8.5" stroke="${c}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const wave=()=>`<span class="wave"><i></i><i></i><i></i><i></i></span>`;

/* Modules really present in Yumi/Sources/App/Modules. Values are fictive. */
const MODS=[
 {k:"cc",n:"Claude Code",i:"term",c:"#8B9CFF",v:"2",u:"sessions",s:"1 attend ton accord"},
 {k:"ag",n:"Agenda",i:"cal",c:"#FF8A7A",v:"14:30",s:"Point design · dans 18 min"},
 {k:"mu",n:"Musique",i:"music",c:"#FF6FA8",v:"Says",s:"Nils Frahm"},
 {k:"fo",n:"Focus",i:"focus",c:"#F2B36B",v:"18:42",s:"Session de 25 min"},
 {k:"ml",n:"Mail",i:"mail",c:"#6FB4FF",v:"4",u:"non lus",s:"Facture Figma"},
 {k:"gh",n:"GitHub",i:"git",c:"#C9D1D9",v:"3",u:"PR",s:"#32 fusionnée"},
 {k:"no",n:"Notes",i:"note",c:"#FFD36B",v:"12",s:"Idées vidéo alpha 11"},
 {k:"nt",n:"Notion",i:"notion",c:"#E6E6E6",v:"5",u:"tâches",s:"2 pour aujourd'hui"},
 {k:"st",n:"Temps d'écran",i:"screen",c:"#9D8BFF",v:"3 h 12",s:"Xcode en tête"},
 {k:"we",n:"Météo",i:"sun",c:"#7FD8FF",v:"12°",s:"Paris · éclaircies"}];
const CMD="git push origin main", WHY="Envoie 3 commits sur GitHub (estebanbaigts/Yumi). Difficile à annuler.";
const SCENE_NAMES=["", "cafe","clope","casque","soleil","nuage","siffle","dodo","epuise"];
const MOODS_LIST=["neutre","heureux","curieux","concentre","reflechi","surpris","inquiet","agace","clin","sommeil"];
const POSES=["saut","celebrer","salut","etirer","ecraser","secouer"];

/* Character panel: the same real Yumi in every direction, framed by that direction's controls. */
function charPanel(dir,big=110){
 return `<div class="row" style="gap:18px;align-items:center;height:100%">
  <div style="flex:none">${Y(big,"neutre","calm","","")}</div>
  <div class="grow col" style="gap:7px;font-size:11.5px">
   <div class="mut">Humeurs (moteur d'origine)</div><div style="display:flex;flex-wrap:wrap;gap:4px">${MOODS_LIST.map(m=>`<span data-mood="${m}" style="${chipCss(dir)}">${m}</span>`).join("")}</div>
   <div class="mut">Habitudes et poses</div><div style="display:flex;flex-wrap:wrap;gap:4px">${SCENE_NAMES.slice(1).map(s=>`<span data-scene="${s}" style="${chipCss(dir)}">${SCENES[s]?SCENES[s].label:s}</span>`).join("")}${POSES.map(p=>`<span data-pose="${p}" style="${chipCss(dir)}">${p}</span>`).join("")}</div>
  </div></div>`;}
const chipCss=d=>({A:"padding:3px 8px;border-radius:99px;color:var(--ifg,var(--pfg));box-shadow:inset 0 0 0 1px rgba(255,255,255,.14)",B:"padding:4px 9px;border-radius:99px;background:rgba(255,255,255,.16)",C:"padding:2px 0;margin-right:8px;text-decoration:underline;text-underline-offset:3px;text-decoration-color:rgba(237,231,220,.25)",D:"padding:3px 9px;border-radius:99px;background:rgba(199,125,255,.16);box-shadow:inset 0 0 0 1px rgba(199,125,255,.35)",E:"padding:2px 7px;border-radius:5px;background:#2C2C2E",F:"padding:5px 11px;border-radius:14px;background:rgba(157,139,255,.22)"})[d];

/* ================= the six directions ================= */
const DIRS={};
const MAC_STATES=[["replie","Repliée"],["ouverte","Ouverte"],["modules","Accueil et modules"],["chat","Chat"],["approbation","Approbation"],["session","Session d'agent"],["termine","Terminé"],["personnage","Personnage"],["navigation","Navigation"]];
const PH_STATES=[["aujourdhui","Aujourd'hui"],["conversation","Conversation"],["approbations","Approbations"],["agenda","Agenda et rappels"],["modules","Modules"],["reglages","Réglages"],["personnage","Personnage"],["liaison","Liaison Mac"]];

/* ---------------------------------------------------------------- A */
DIRS.A={name:"Une chose à la fois",style:"Obsidian",
 pitch:"L'île ne montre qu'une page à la fois, comme une pile de cartes qu'on fait défiler. Les actions sensibles se confirment en maintenant le bouton appuyé, jamais d'un simple clic.",
 model:[["Navigation","Pages horizontales avec points, flèches sur les bords, molette ou glisser à deux doigts. Pas de barre d'icônes."],["Boutons","Une seule capsule blanche par page. « Maintenir pour… » remplit la capsule pendant 1 s."],["Approbation","Maintenir pour autoriser, croix discrète pour refuser."],["Chat","Clic sur Yumi : une seule ligne, la réponse s'écrit dessous."],["iPhone","Pas de barre d'onglets : une pile verticale de cartes plein écran. Yumi en haut à gauche ouvre le menu."]],
 pro:["Impossible d'approuver par erreur.","Très calme : une info, un geste.","L'île reste petite."],con:["Plus lent pour enchaîner plusieurs actions.","Les modules sont moins visibles d'un coup d'œil.","Maintenir est moins découvrable qu'un bouton."]};
DIRS.A.mac=s=>{
 const hold=(label,to,c="#F5F5F7",t=1)=>`<button class="hold" data-hold="${to}" style="--holdc:${c};--holdt:${t}s;height:34px;padding:0 18px;border-radius:99px;box-shadow:inset 0 0 0 1.5px ${c};color:var(--ifg);font-weight:600;font-size:13px">${label}</button>`;
 const pages=[
  ["Agenda","#FF8A7A",`<div class="tnum" style="font:600 46px/1 var(--sfd);letter-spacing:-.03em">14:30</div><div style="font-weight:600;margin-top:4px">Point design <span class="mut" style="font-weight:500">· dans 18 min</span></div>`,hold("Maintenir pour rejoindre","replie","#FF8A7A")],
  ["Claude Code","#8B9CFF",`<div class="tnum" style="font:600 46px/1 var(--sfd)">04:12</div><div class="mono mut" style="font-size:12px;margin-top:6px">xcodebuild test</div>`,`<button data-go="session" style="height:34px;padding:0 18px;border-radius:99px;background:#F5F5F7;color:#000;font-weight:600;font-size:13px">Voir la session</button>`],
  ["Musique","#FF6FA8",`<div style="font:600 34px/1 var(--sfd)">Says</div><div class="mut" style="margin-top:6px">Nils Frahm ${wave()}</div>`,`<div class="row" style="gap:16px">${ic("prev",18)}<span style="width:38px;height:38px;border-radius:50%;background:#F5F5F7;display:grid;place-items:center">${ic("pause",16,"#000",2.4)}</span>${ic("next",18)}</div>`],
  ["Focus","#F2B36B",`<div class="tnum" style="font:600 46px/1 var(--sfd)">18:42</div><div class="mut" style="margin-top:4px">restantes sur 25 min</div>`,hold("Maintenir pour arrêter","ouverte","#F2B36B")],
  ["Mail","#6FB4FF",`<div style="font:600 46px/1 var(--sfd)">4</div><div class="mut" style="margin-top:4px">non lus · dernier : facture Figma</div>`,`<button style="height:34px;padding:0 18px;border-radius:99px;background:#F5F5F7;color:#000;font-weight:600;font-size:13px">Lire</button>`]];
 const pager=(start=0)=>`<div class="pager" style="height:150px"><div class="track" data-i="${start}" style="transform:translateX(-${start*100}%)">${pages.map(([n,c,body,act])=>`<div class="row" style="padding:0 34px;gap:22px;align-items:center;height:150px"><div class="grow">${eb(n,c)}<div style="margin-top:8px">${body}</div></div><div>${act}</div></div>`).join("")}</div></div>
  <div class="row" style="position:absolute;left:0;right:0;bottom:12px;justify-content:center;color:var(--ifg)"><div class="dots">${pages.map((_,i)=>`<i data-page="${i}" class="${i===start?"on":""}"></i>`).join("")}</div></div>
  <button data-page="-1" style="position:absolute;left:6px;top:96px;color:var(--imut)">${ic("left",18)}</button><button data-page="+1" style="position:absolute;right:6px;top:96px;color:var(--imut)">${ic("right",18)}</button>`;
 switch(s){
 case"replie":return{w:320,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:12px;top:4px">${Y(24,"neutre")}</div><div class="tnum" style="position:absolute;right:14px;top:8px;font-size:12.5px;font-weight:600">14:30</div></div>`};
 case"ouverte":return{w:560,h:226,html:`<div style="position:absolute;right:18px;top:36px" data-go="chat" title="Parler à Yumi">${Y(30,"neutre")}</div>`+pager(0)};
 case"navigation":return{w:560,h:226,html:`<div style="position:absolute;right:18px;top:36px">${Y(30,"curieux")}</div>`+pager(2)};
 case"modules":return{w:640,h:250,html:`${eb("Tout · fais défiler")}<div style="display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;margin-top:10px;padding-bottom:8px;scrollbar-width:none">${MODS.map(m=>`<div data-go="navigation" style="scroll-snap-align:start;flex:0 0 140px;height:150px;border-radius:20px;background:rgba(255,255,255,.045);padding:14px;display:flex;flex-direction:column;justify-content:space-between"><span style="color:${m.c}">${ic(m.i,18)}</span><div><div class="tnum" style="font:600 26px/1 var(--sfd)">${m.v}</div><div class="mut" style="font-size:11.5px;margin-top:4px">${m.n}</div></div></div>`).join("")}</div>`};
 case"chat":return{w:560,h:210,html:`<div class="row" style="padding:0 14px">${Y(40,"concentre","work")}<div class="grow"><div class="mut" style="font-size:12.5px">Range mes téléchargements par type</div><div class="caret" style="font:500 17px/1.35 var(--sfd);margin-top:4px">48 fichiers trouvés. Je range les PDF dans Documents</div></div></div><div style="padding:14px 14px 0"><div class="row mut" style="font-size:11.5px;margin-bottom:6px">${ic("bolt",12)}<span class="mono">12 PDF → ~/Documents</span><span style="margin-left:auto">3 / 5</span></div><div class="line"><i></i></div></div><div class="mut" style="position:absolute;bottom:14px;left:0;right:0;text-align:center;font-size:11.5px">Maintiens <span class="keycap">⌥</span> pour parler · <span class="keycap">esc</span> pour fermer</div>`};
 case"approbation":return{w:540,h:228,html:`<div class="row" style="padding:0 12px">${Y(52,"surpris","warn")}<div class="grow">${eb("Claude Code veut lancer","#FFB547")}<div class="mono" style="font-size:14px;margin-top:6px;color:#FFE3B0">${CMD}</div><div class="mut" style="font-size:12px;margin-top:4px">${WHY}</div></div></div>
  <div class="row" style="position:absolute;left:0;right:0;bottom:18px;justify-content:center;gap:14px"><button data-go="ouverte" title="Refuser" style="width:36px;height:36px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(255,255,255,.18);display:grid;place-items:center;color:var(--imut)">${ic("x",15)}</button>${hold("Maintenir pour autoriser","session","#30D158",1.2)}<span class="mut" style="font-size:11.5px">Toujours</span></div>`};
 case"session":return{w:520,h:200,html:`<div class="row" style="padding:0 12px;gap:18px">${Y(64,"concentre","work","cafe")}<div class="grow">${eb("Claude Code · refonte-ile","#8B9CFF")}<div class="tnum" data-timer="252" style="font:600 42px/1 var(--sfd);margin-top:6px">04:12</div><div class="mono mut" style="font-size:12px;margin-top:6px">xcodebuild test</div></div>${hold("Maintenir pour arrêter","ouverte","#FF453A")}</div><div style="position:absolute;left:32px;right:32px;bottom:16px" class="line"><i></i></div>`};
 case"termine":return{w:500,h:180,html:`<div class="row" style="padding:0 12px;gap:18px" data-auto="replie:5200">${Y(62,"heureux","done","","celebrer")}<div class="grow">${eb("refonte-ile · 6 min","#30D158")}<div class="tnum" style="font:600 36px/1.05 var(--sfd);margin-top:6px">142 / 142</div><div class="mut" style="font-size:12px">tests passés</div></div><button data-toast="Terminal ouvert" style="height:34px;padding:0 18px;border-radius:99px;background:#F5F5F7;color:#000;font-weight:600;font-size:13px">Terminal</button></div><div class="mut" style="position:absolute;bottom:12px;left:0;right:0;text-align:center;font-size:11px">L'île se replie toute seule dans 5 s</div>`};
 case"personnage":return{w:600,h:240,html:charPanel("A",120)};
 }};
DIRS.A.ph=s=>{
 const top=`<div class="row" style="justify-content:space-between;margin:4px 0 10px"><button data-toggle=".amenu" class="row" style="gap:8px">${Y(30,"neutre")}<span style="font-weight:600;font-size:14px">${({aujourdhui:"Maintenant",conversation:"Parler",approbations:"Demandes",agenda:"Agenda",modules:"Modules",reglages:"Réglages",personnage:"Yumi",liaison:"Mac"})[s]} ${ic("down",13)}</span></button><span class="mut" style="font-size:12px">lun. 23</span></div>`;
 const menu=`<div class="scrim amenu" data-toggle=".amenu"></div><div class="sheet amenu" style="background:#0E0E10;border-radius:30px 30px 0 0;padding:22px 26px 46px">${[["aujourdhui","Maintenant"],["conversation","Parler à Yumi"],["approbations","Demandes · 2"],["agenda","Agenda"],["modules","Modules"],["personnage","Yumi"],["reglages","Réglages"],["liaison","Mon Mac"]].map(([k,n])=>`<div data-go="${k}" style="font:600 24px/1.6 var(--sfd);color:${k===s?"#fff":"#6E6E73"}">${n}</div>`).join("")}</div>`;
 const big=(ebt,c,b,act)=>`<div style="scroll-snap-align:start;height:440px;border-radius:30px;background:#0E0E10;padding:24px;display:flex;flex-direction:column;justify-content:space-between;margin-bottom:12px">${eb(ebt,c)}<div>${b}</div>${act}</div>`;
 const hold=(l,to,c)=>`<button class="hold" data-hold="${to}" style="--holdc:${c};height:52px;width:100%;border-radius:99px;box-shadow:inset 0 0 0 1.5px ${c};font-weight:650;font-size:15px">${l}</button>`;
 let b="";
 switch(s){
 case"aujourdhui":b=`<div style="height:470px;overflow-y:auto;scroll-snap-type:y mandatory;scrollbar-width:none">${big("Demande · Claude Code","#FFB547",`<div class="mono" style="font-size:17px;color:#FFE3B0">${CMD}</div><div class="mut" style="margin-top:8px;font-size:14px">${WHY}</div>`,hold("Maintenir pour autoriser","approbations","#30D158"))}${big("Agenda · dans 18 min","#FF8A7A",`<div class="tnum" style="font:600 64px/1 var(--sfd)">14:30</div><div style="font-size:18px;font-weight:600;margin-top:6px">Point design</div>`,hold("Maintenir pour rejoindre","agenda","#FF8A7A"))}${big("Musique","#FF6FA8",`<div style="font:600 40px/1 var(--sfd)">Says</div><div class="mut">Nils Frahm</div>`,`<div class="row" style="justify-content:center;gap:30px">${ic("prev",26)}${ic("pause",30)}${ic("next",26)}</div>`)}</div><div class="mut" style="text-align:center;font-size:11.5px;margin-top:4px">Fais défiler : une carte à la fois</div>`;break;
 case"conversation":b=`<div style="margin-top:60px;text-align:center"><div class="mut" style="font-size:14px">« Il reste quoi sur la refonte ? »</div><div style="font:500 22px/1.3 var(--sfd);margin:16px 6px">Les tests passent. Il manque les réglages et la relecture de la PR #33.</div></div><div style="position:absolute;left:0;right:0;bottom:60px;text-align:center"><button class="hold" data-hold="conversation" style="--holdc:#F5F5F7;width:84px;height:84px;border-radius:50%;box-shadow:inset 0 0 0 1.5px #F5F5F7">${ic("mic",30)}</button><div class="mut" style="font-size:12px;margin-top:10px">Maintiens pour parler · touche pour écrire</div></div>`;break;
 case"approbations":b=`<div class="mut" style="font-size:12px;margin-bottom:8px">1 sur 2</div>${big("Claude Code · Yumi","#FFB547",`<div class="mono" style="font-size:18px;color:#FFE3B0">${CMD}</div><div class="mut" style="margin-top:10px">${WHY}</div>`,`<div class="col" style="gap:12px">${hold("Maintenir pour autoriser","aujourdhui","#30D158")}<div class="row" style="justify-content:space-between;font-size:13px"><span data-go="aujourdhui" style="color:#FF6961">Refuser</span><span class="mut">Toujours autoriser</span></div></div>`)}`;break;
 case"agenda":b=`<div style="position:relative;padding-left:58px">${[["09:30","Stand-up","#8B9CFF"],["12:30","Déjeuner",""],["14:12","maintenant","#FF453A"],["14:30","Point design","#FF8A7A"],["16:00","Focus · refonte","#F2B36B"],["18:30","Sport","#3DDC97"]].map(([h,t,c])=>t==="maintenant"?`<div style="position:relative;height:0;border-top:1.5px solid #FF453A;margin:6px 0 14px"><span style="position:absolute;left:-58px;top:-9px;font-size:11px;color:#FF453A;font-weight:700">${h}</span></div>`:`<div style="position:relative;height:62px"><span class="tnum mut" style="position:absolute;left:-58px;top:0;font-size:12px">${h}</span><div style="border-left:2px solid ${c||"#2C2C2E"};padding-left:12px;font-weight:600">${t}</div></div>`).join("")}</div><div class="mut" style="font-size:12px">Rappels : Relire la PR #33 · Facture client</div>`;break;
 case"modules":b=`<div class="pager"><div class="track" data-i="0">${MODS.slice(0,5).map(m=>`<div style="padding:0 2px">${big(m.n,m.c,`<div class="tnum" style="font:600 58px/1 var(--sfd)">${m.v}</div><div class="mut" style="margin-top:8px">${m.s}</div>`,"")}</div>`).join("")}</div></div><div class="dots" style="color:#fff">${MODS.slice(0,5).map((_,i)=>`<i data-page="${i}" class="${i?"":"on"}"></i>`).join("")}</div><div class="mut" style="font-size:11px;margin-top:8px"><span class="tag">Proposition</span> cet écran n'existe pas encore sur iPhone.</div>`;break;
 case"reglages":b=["Mac relié · MacBook Pro","Notifications · demandes","Voix · douce","Mémoire · 23 souvenirs","Habitude au travail · café","Agenda et rappels · autorisé"].map(t=>{const [a,z]=t.split(" · ");return `<div class="row" style="justify-content:space-between;padding:16px 0;border-bottom:1px solid #1C1C1F;font-size:16px"><span>${a}</span><span class="mut">${z}</span></div>`}).join("");break;
 case"personnage":b=`<div style="text-align:center;margin:20px 0 14px">${Y(150,"heureux","calm","cafe")}</div>${charPanel("A",0).replace(/<div style="flex:none">.*?<\/div>/,"")}`;break;
 case"liaison":b=`<div style="text-align:center;margin-top:40px">${Y(80,"curieux")}<div style="font:600 24px var(--sfd);margin:16px 0 6px">Relie ton Mac</div><div class="mut" style="font-size:14px;margin:0 14px 24px">Sur le Mac : Réglages › iPhone, puis scanne le code.</div>${hold("Maintenir pour scanner","aujourdhui","#F5F5F7")}<div style="color:#30D158;font-size:12px;margin-top:16px">● Dernière synchro il y a 2 min</div></div>`;break;}
 return top+b+menu;};

/* ---------------------------------------------------------------- B */
DIRS.B={name:"Gouttes",style:"Liquid Glass",
 pitch:"L'île est en verre et les actions s'en détachent comme des gouttes : chaque bouton est une petite bulle sous l'île. On approuve en faisant glisser, comme pour déverrouiller.",
 model:[["Navigation","Une capsule de verre qui glisse d'un module à l'autre en se déformant."],["Boutons","Des gouttes séparées, sous l'île, qui naissent et disparaissent avec l'état."],["Approbation","Glisser pour autoriser ; la goutte « Refuser » flotte à côté."],["Chat","Le champ de saisie est une goutte sous l'île ; la réponse s'affiche dans l'île."],["iPhone","Barre d'onglets de verre flottante, widgets en mosaïque, détails dans des feuilles qui montent du bas."]],
 pro:["Très « Apple 2026 », spectaculaire en vidéo.","Glisser pour autoriser : sûr et naturel au trackpad.","L'île reste compacte, les actions débordent."],con:["Lisibilité qui dépend du fond d'écran.","Flou coûteux en continu.","Gouttes sous la notch : peuvent gêner le haut des fenêtres."]};
const drop=(inner,go,extra="")=>`<button ${go?`data-go="${go}"`:""} class="glass" style="height:36px;padding:0 15px;border-radius:99px;color:#fff;font-weight:600;font-size:12.5px;display:inline-flex;align-items:center;gap:6px;animation:at-in .45s .25s both;${extra}">${inner}</button>`;
const slider=(label,to,c="#5EF2A5")=>`<div class="slider glass" data-slide="${to}" style="width:100%"><span class="shim">${label}</span><span class="knob" style="background:${c};color:#06261A">${ic("arrow",18,"#06261A",2.6)}</span></div>`;
DIRS.B.mac=s=>{
 const segnav=(cur)=>{const it=[["grid","Tout"],["cal","Agenda"],["term","Agents"],["music","Musique"],["focus","Focus"],["chat","Chat"]];return `<div class="glass" style="position:absolute;left:50%;bottom:10px;transform:translateX(-50%);display:flex;padding:4px;border-radius:99px;gap:2px">${it.map(([i,n],k)=>`<span data-seg="${k}" class="${k===cur?"on":""}" style="display:flex;align-items:center;gap:5px;height:28px;padding:0 11px;border-radius:99px;font-size:11.5px;font-weight:650;transition:.35s;${k===cur?"background:rgba(255,255,255,.92);color:#0B1020":"color:rgba(255,255,255,.8)"}">${ic(i,14)}<span class="lbl" style="${k===cur?"":"display:none"}">${n}</span></span>`).join("")}</div>`};
 switch(s){
 case"replie":return{w:300,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:12px;top:4px">${Y(24)}</div><div style="position:absolute;right:14px;top:8px">${wave()}</div></div>`,below:`<div style="margin-top:40px;margin-left:120px" class="row">${drop(ic("cal",14)+"14:30","ouverte","height:30px;padding:0 11px")}</div>`};
 case"ouverte":return{w:520,h:160,html:`<div class="row" style="gap:16px">${Y(60,"neutre")}<div class="grow">${eb("Dans 18 min","rgba(255,255,255,.7)")}<div style="font:650 26px/1.1 var(--sfd);margin-top:4px">Point design · 14:30</div><div class="mut" style="font-size:12.5px;margin-top:3px">Meet · avec Léa et Tom</div></div></div>`,below:`<div class="row" style="margin-top:172px;gap:8px;justify-content:center">${drop(ic("cal",14)+"Rejoindre","replie","background:rgba(255,138,122,.55)")}${drop(ic("term",14)+"Agent · 04:12","session")}${drop(ic("music",14)+"Says","navigation")}${drop(ic("chat",14),"chat","width:36px;padding:0;justify-content:center")}</div>`};
 case"modules":return{w:600,h:248,html:`<div style="position:relative;height:190px">${MODS.map((m,i)=>{const sz=[96,84,74,70,64,60,56,54,52,50][i],pos=[[10,8],[118,0],[214,30],[296,0],[378,20],[452,0],[150,104],[228,118],[316,92],[400,104]][i];return `<div data-go="navigation" class="glass" style="position:absolute;left:${pos[0]}px;top:${pos[1]}px;width:${sz}px;height:${sz}px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;animation:at-in .5s ${i*40}ms both"><span style="color:${m.c}">${ic(m.i,sz>70?18:14)}</span><b class="tnum" style="font-size:${sz>70?15:12}px">${m.v}</b>${sz>70?`<span style="font-size:10px;opacity:.75">${m.n}</span>`:""}</div>`}).join("")}</div><div class="mut" style="text-align:center;font-size:11px">Plus la bulle est grosse, plus c'est important maintenant</div>`};
 case"chat":return{w:540,h:200,html:`<div class="col" style="gap:10px"><div class="glass" style="align-self:flex-end;padding:8px 13px;border-radius:18px 18px 5px 18px;font-size:13px">Range mes téléchargements par type</div><div class="row" style="align-items:flex-start">${Y(34,"concentre","work")}<div class="grow"><div class="caret" style="font-size:13.5px;line-height:1.4">48 fichiers trouvés. Les PDF partent dans Documents, les images dans Images</div><div class="row mut" style="font-size:11.5px;margin-top:6px">${ic("bolt",12)}<span class="mono">12 PDF → ~/Documents</span></div></div></div></div>`,below:`<div class="glass row" style="margin-top:210px;width:420px;height:44px;border-radius:22px;padding:0 6px 0 16px;color:rgba(255,255,255,.75);font-size:13px;animation:at-in .45s .2s both">Demande à Yumi…<span style="margin-left:auto;display:flex;gap:4px"><span style="width:32px;height:32px;border-radius:50%;display:grid;place-items:center">${ic("mic",16)}</span><span style="width:32px;height:32px;border-radius:50%;background:#7FD8FF;display:grid;place-items:center">${ic("arrow",15,"#06202E",2.4)}</span></span></div>`};
 case"approbation":return{w:500,h:206,html:`<div class="row" style="gap:14px">${Y(48,"surpris","warn")}<div class="grow">${eb("Claude Code veut lancer","#FFD37A")}<div class="mono" style="font-size:13.5px;margin-top:4px">${CMD}</div><div class="mut" style="font-size:11.5px;margin-top:3px">${WHY}</div></div></div><div style="margin-top:14px">${slider("Glisse pour autoriser","session")}</div>`,below:`<div class="row" style="margin-top:216px;gap:8px;justify-content:center">${drop(ic("x",13)+"Refuser","ouverte","background:rgba(255,69,58,.5)")}${drop("Toujours autoriser",null)}</div>`};
 case"session":return{w:500,h:170,html:`<div class="row" style="gap:16px">${Y(66,"concentre","work","clope")}<div class="grow">${eb("Claude Code · refonte-ile","rgba(255,255,255,.7)")}<div class="tnum" data-timer="252" style="font:650 34px/1 var(--sfd);margin-top:4px">04:12</div><div class="mono mut" style="font-size:12px;margin-top:4px">xcodebuild test · 3 fichiers modifiés</div></div></div><div class="line" style="margin-top:12px"><i></i></div>`,below:`<div class="row" style="margin-top:180px;gap:8px;justify-content:center">${drop(ic("stop",13)+"Arrêter","ouverte")}${drop(ic("term",13)+"Terminal",null)}</div>`};
 case"termine":return{w:480,h:150,html:`<div class="row" style="gap:16px" data-auto="replie:6000">${Y(60,"heureux","done","soleil","celebrer")}<div class="grow">${eb("Terminé · 6 min","#9BF0C8")}<div style="font:650 24px/1.15 var(--sfd);margin-top:4px">142 tests sur 142</div><div class="mut" style="font-size:12px">refonte-ile · prêt à relire</div></div>${chk(40)}</div>`,below:`<div class="row" style="margin-top:160px;gap:8px;justify-content:center">${drop("Voir le diff",null,"background:rgba(94,242,165,.4)")}${drop("Merci","replie")}</div>`};
 case"personnage":return{w:600,h:240,html:charPanel("B",120)};
 case"navigation":return{w:540,h:196,html:`<div class="pane on" data-pane="0"><div class="row">${Y(44)}<div><b>Tout va bien</b><div class="mut" style="font-size:12px">2 agents · 4 mails · 14:30 Point design</div></div></div></div><div class="pane" data-pane="1"><div class="row">${Y(44,"curieux")}<div><b style="font-size:20px">14:30 Point design</b><div class="mut" style="font-size:12px">dans 18 min</div></div></div></div><div class="pane" data-pane="2"><div class="row">${Y(44,"concentre","work","cafe")}<div><b style="font-size:20px">refonte-ile · 04:12</b><div class="mut mono" style="font-size:12px">xcodebuild test</div></div></div></div><div class="pane" data-pane="3"><div class="row">${Y(44,"heureux","joy","casque")}<div class="grow"><b style="font-size:20px">Says</b><div class="mut" style="font-size:12px">Nils Frahm</div><div class="line" style="margin-top:8px"><i style="background:#FF6FA8"></i></div></div></div></div><div class="pane" data-pane="4"><div class="row">${Y(44,"concentre")}<b class="tnum" style="font-size:30px">18:42</b></div></div><div class="pane" data-pane="5"><div class="row">${Y(44,"curieux")}<span class="mut">Demande à Yumi…</span></div></div>`+segnav(0)};
 }};
DIRS.B.ph=s=>{
 const tabs=[["aujourdhui","sun","Aujourd'hui"],["conversation","chat","Parler"],["approbations","bell","Demandes"],["reglages","gear","Réglages"]];
 const cur={agenda:"aujourdhui",modules:"aujourdhui",personnage:"reglages",liaison:"reglages"}[s]||s;
 const tb=`<div class="glass" style="position:absolute;left:22px;right:22px;bottom:22px;height:62px;border-radius:31px;display:flex;justify-content:space-around;align-items:center;z-index:15">${tabs.map(([k,i,n])=>`<span data-go="${k}" style="display:flex;flex-direction:column;align-items:center;gap:2px;font-size:10px;font-weight:650;padding:6px 8px;border-radius:24px;${k===cur?"background:rgba(255,255,255,.9);color:#0B1020":""}">${ic(i,19)}${n}${k==="approbations"?`<i style="position:absolute;margin:-2px 0 0 18px;width:7px;height:7px;border-radius:50%;background:#FF453A"></i>`:""}</span>`).join("")}</div><div class="mut" style="position:absolute;bottom:90px;left:0;right:0;text-align:center;font-size:10px;z-index:14"><span class="tag">Proposition</span> 4ᵉ onglet Demandes</div>`;
 const sheet=(sel,inner)=>`<div class="scrim ${sel}" data-toggle=".${sel}"></div><div class="sheet ${sel} glass" style="border-radius:32px 32px 0 0;padding:10px 20px 40px;background:rgba(30,30,50,.6)"><div style="width:36px;height:5px;border-radius:3px;background:rgba(255,255,255,.4);margin:0 auto 14px"></div>${inner}</div>`;
 const w=(inner,span=1,tog="",h=120)=>`<div ${tog?`data-toggle=".${tog}"`:""} class="glass" style="grid-column:span ${span};height:${h}px;border-radius:24px;padding:13px;display:flex;flex-direction:column;justify-content:space-between">${inner}</div>`;
 const T=t=>`<div style="font:700 30px/1.1 var(--sfd);margin:8px 0 14px">${t}</div>`;
 let b="";
 switch(s){
 case"aujourdhui":b=`<div class="row" style="justify-content:space-between">${T("Aujourd'hui")}${Y(44)}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${w(`${eb("Demande","#FFD37A")}<div class="mono" style="font-size:13px">${CMD}</div><div style="font-size:12px;opacity:.75">Touche pour décider</div>`,2,"sh1",110)}${w(`<span style="color:#FF8A7A">${ic("cal",18)}</span><div><b class="tnum" style="font-size:24px">14:30</b><div style="font-size:12px;opacity:.75">Point design</div></div>`,1,"sh2")}${w(`<span style="color:#FF6FA8">${ic("music",18)}</span><div><b>Says</b><div style="font-size:12px;opacity:.75">Nils Frahm</div></div>`)}${w(`<div class="row"><span style="color:#8B9CFF">${ic("term",18)}</span><b>2 agents</b><span style="margin-left:auto;font-size:12px" class="tnum">04:12</span></div><div class="line"><i></i></div>`,2,"",84)}</div>`+sheet("sh1",`${eb("Claude Code · Yumi","#FFD37A")}<div class="mono" style="font-size:16px;margin:8px 0">${CMD}</div><div style="font-size:13px;opacity:.8;margin-bottom:16px">${WHY}</div>${slider("Glisse pour autoriser","aujourdhui")}<div class="row" style="justify-content:space-between;margin-top:12px;font-size:13px"><span data-toggle=".sh1" style="color:#FF9B93">Refuser</span><span style="opacity:.7">Toujours autoriser</span></div>`)+sheet("sh2",`${eb("Agenda","#FF8A7A")}<div style="font:700 40px var(--sfd)">14:30</div><div style="font-size:17px;font-weight:600">Point design</div><div style="opacity:.75;margin-bottom:16px">Meet · dans 18 min</div>${drop("Rejoindre",null,"width:100%;justify-content:center;height:46px;background:rgba(255,138,122,.6)")}`);break;
 case"conversation":b=`<div class="row">${Y(40)}<b>Yumi</b><span style="font-size:12px;color:#9BF0C8;margin-left:auto">● Mac relié</span></div><div class="col" style="gap:8px;margin-top:16px"><div class="glass" style="align-self:flex-end;padding:9px 13px;border-radius:18px 18px 5px 18px;font-size:14px;background:rgba(255,255,255,.85);color:#0B1020">Il reste quoi sur la refonte ?</div><div class="glass" style="padding:9px 13px;border-radius:18px 18px 18px 5px;font-size:14px;max-width:85%">Les tests passent. Il manque les réglages et la relecture de la PR #33. Je lance la relecture ?</div><div class="row" style="gap:6px">${drop("Oui, vas-y",null,"height:30px")}${drop("Plus tard",null,"height:30px")}</div></div><div class="glass row" style="position:absolute;left:16px;right:16px;bottom:96px;height:46px;border-radius:23px;padding:0 6px 0 16px;font-size:14px;opacity:.95">Message<span style="margin-left:auto;width:34px;height:34px;border-radius:50%;background:#7FD8FF;display:grid;place-items:center">${ic("mic",16,"#06202E")}</span></div>`;break;
 case"approbations":b=T("Demandes")+[["#FFD37A",CMD,WHY],["#FF9B93","rm -rf build/","Supprime le dossier de build (régénérable)."]].map(([c,cm,wh],i)=>`<div class="glass" style="border-radius:26px;padding:16px;margin-bottom:12px">${eb("Claude Code · il y a "+(i+1)+" min",c)}<div class="mono" style="font-size:14px;margin:6px 0">${cm}</div><div style="font-size:12.5px;opacity:.75;margin-bottom:12px">${wh}</div>${slider("Glisse pour autoriser","aujourdhui")}<div style="text-align:center;font-size:12px;margin-top:8px;color:#FF9B93" data-go="aujourdhui">Refuser</div></div>`).join("");break;
 case"agenda":b=T("Agenda")+`<div style="display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;margin-bottom:14px">${["L 23","M 24","M 25","J 26","V 27","S 28"].map((d,i)=>`<span class="glass" style="flex:0 0 52px;height:62px;border-radius:20px;display:grid;place-items:center;font-size:13px;font-weight:650;${i?"":"background:rgba(255,255,255,.9);color:#0B1020"}">${d.replace(" ","<br>")}</span>`).join("")}</div>`+[["09:30","Stand-up","#8B9CFF"],["14:30","Point design","#FF8A7A"],["16:00","Focus · refonte","#F2B36B"],["18:30","Sport","#5EF2A5"]].map(([h,t,c])=>`<div class="glass row" style="border-radius:20px;padding:12px 14px;margin-bottom:8px"><span style="width:10px;height:10px;border-radius:50%;background:${c}"></span><b class="tnum">${h}</b><span>${t}</span></div>`).join("");break;
 case"modules":b=T("Modules")+`<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px">${MODS.map(m=>`<div class="glass" style="aspect-ratio:1;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center"><span style="color:${m.c}">${ic(m.i,18)}</span><b class="tnum" style="font-size:13px">${m.v}</b></div>`).join("")}</div><div style="font-size:11px;opacity:.7;margin-top:10px"><span class="tag">Proposition</span> écran absent de l'app iPhone actuelle</div>`;break;
 case"reglages":b=T("Réglages")+[["laptop","#0A84FF","Mac relié","liaison"],["user","#B49BFF","Yumi","personnage"],["bell","#FF453A","Notifications",""],["mem","#30D158","Mémoire",""],["mic","#FF9F0A","Voix",""]].map(([i,c,t,go])=>`<div ${go?`data-go="${go}"`:""} class="glass row" style="border-radius:20px;padding:12px 14px;margin-bottom:8px"><span style="width:30px;height:30px;border-radius:50%;background:${c};display:grid;place-items:center">${ic(i,15,"#fff")}</span><span class="grow">${t}</span>${ic("right",14)}</div>`).join("");break;
 case"personnage":b=T("Yumi")+`<div class="glass" style="border-radius:28px;padding:18px;text-align:center">${Y(130,"heureux","calm","casque")}</div><div style="margin-top:12px">${charPanel("B",0).replace(/<div style="flex:none">.*?<\/div>/,"")}</div>`;break;
 case"liaison":b=T("Ton Mac")+`<div class="glass" style="border-radius:28px;padding:22px;text-align:center">${Y(70,"curieux")}<div style="margin:12px 0 16px;font-size:14px;opacity:.85">Approche ton iPhone du Mac. Yumi s'en occupe.</div>${slider("Glisse pour relier","aujourdhui","#7FD8FF")}</div>`;break;}
 return b+tb;};

/* ---------------------------------------------------------------- C */
DIRS.C={name:"Commande",style:"Studio Minimal",
 pitch:"Tout se fait au clavier ou à la voix. L'île ouverte est une ligne de commande élégante : on tape, Yumi propose, on valide d'une touche. Une mise en page éditoriale, des mots plutôt que des boutons.",
 model:[["Navigation","On tape « / » puis le nom du module, ou on choisit dans la liste numérotée. Les onglets sont des mots soulignés."],["Boutons","Des touches : A autoriser, R refuser, ↵ action principale. Pas de boutons ronds."],["Approbation","Une phrase en clair, puis trois touches."],["Chat","Le même champ que les commandes : si ce n'est pas une commande, c'est une question à Yumi."],["iPhone","Un journal chronologique ; les demandes se balaient (droite : autoriser, gauche : refuser)."]],
 pro:["Le plus rapide pour quelqu'un qui code.","Très lisible, identité éditoriale forte.","Une seule entrée pour tout : commandes, chat, modules."],con:["Moins évident pour un nouvel utilisateur.","Peu de place pour l'image (pochettes, etc.).","Le serif peut sembler moins « système »."]};
DIRS.C.mac=s=>{
 const field=(ph,val="")=>`<div class="row" style="border-bottom:1px solid rgba(237,231,220,.16);padding-bottom:8px">${Y(26)}<input data-cmd placeholder="${ph}" value="${val}" style="flex:1;font:400 19px var(--serif);color:var(--ifg)"><span class="keycap">/</span></div>`;
 const line=(n,t,sub,go,key="↵")=>`<div data-k="${t.toLowerCase()}" ${go?`data-go="${go}"`:""} class="row" style="padding:6px 0;font-size:13.5px;border-bottom:1px solid rgba(237,231,220,.06)"><span class="mut tnum" style="width:14px">${n}</span><span class="grow">${t} <span class="mut">${sub}</span></span><span class="keycap">${key}</span></div>`;
 switch(s){
 case"replie":return{w:440,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:12px;top:5px">${Y(22)}</div><div class="serif" style="position:absolute;left:44px;top:6px;font-size:14px">Point design</div><div class="serif tnum" style="position:absolute;right:16px;top:6px;font-size:14px">14:30</div></div>`};
 case"ouverte":case"navigation":return{w:560,h:250,html:`<div style="padding:4px 10px">${field("Que veux-tu faire ?")}<div class="cmdlist" style="margin-top:6px">${line(1,"Rejoindre Point design","· 14:30","replie")}${line(2,"Répondre à Claude Code","· git push en attente","approbation")}${line(3,"Voir la session refonte-ile","· 04:12","session")}${line(4,"Mettre en pause Says","· Nils Frahm",null,"␣")}${line(5,"/agenda /mail /focus /github","· modules","modules","/")}</div></div>`};
 case"modules":return{w:600,h:262,html:`<div style="padding:0 12px"><div class="row" style="justify-content:space-between">${eb("Index","var(--acc2)")}${Y(24)}</div><div style="columns:2;column-gap:30px;margin-top:6px">${MODS.map(m=>`<div data-go="ouverte" class="row" style="padding:4px 0;break-inside:avoid;border-bottom:1px solid rgba(237,231,220,.08)"><span class="serif tnum" style="font-size:20px;min-width:70px">${m.v}</span><span style="font-size:12.5px">${m.n}</span><span class="mut mono" style="margin-left:auto;font-size:11px">/${m.n.split(" ")[0].toLowerCase().replace("'","")}</span></div>`).join("")}</div></div>`};
 case"chat":return{w:560,h:240,html:`<div style="padding:0 12px"><div style="font-size:12px" class="mut">Toi —</div><div class="serif" style="font-size:15px">Range mes téléchargements par type.</div><div style="font-size:12px;margin-top:10px" class="mut row">${Y(18,"concentre","work")} Yumi —</div><div class="serif caret" style="font-size:17px;line-height:1.35">48 fichiers. Les PDF vont dans Documents, les images dans Images, je garde les .dmg récents</div><div class="mono mut" style="font-size:11.5px;margin-top:6px">→ déplace 12 PDF vers ~/Documents (3/5)</div><div style="position:absolute;left:32px;right:32px;bottom:14px">${field("Continue, ou tape / pour une commande")}</div></div>`};
 case"approbation":return{w:560,h:236,html:`<div style="padding:0 12px"><div class="row" style="justify-content:space-between">${eb("Demande · Claude Code","#F2B36B")}${Y(30,"surpris","warn")}</div><div class="serif" style="font-size:25px;line-height:1.15;margin:4px 0 8px">Pousser trois commits sur <i>main</i> ?</div><div class="mono" style="font-size:12px;border-left:2px solid #F2B36B;padding-left:10px">${CMD}</div><div class="mut" style="font-size:12px;margin-top:4px">${WHY}</div><div class="row" style="gap:22px;margin-top:16px;font-size:13px"><span data-go="session" class="row" style="gap:6px"><span class="keycap" style="background:#9CCB8F;color:#0A0A09">A</span>Autoriser</span><span data-go="ouverte" class="row" style="gap:6px"><span class="keycap">R</span>Refuser</span><span class="row" style="gap:6px"><span class="keycap">⇧A</span>Toujours</span><span class="row mut" style="gap:6px;margin-left:auto"><span class="keycap">?</span>Pourquoi</span></div></div>`};
 case"session":return{w:560,h:236,html:`<div style="padding:0 12px"><div class="row" style="justify-content:space-between"><div>${eb("refonte-ile","#8B9CFF")}<div class="serif tnum" data-timer="252" style="font-size:38px;line-height:1">04:12</div></div>${Y(54,"concentre","work","cafe")}</div><div class="stream mono" data-stream style="font-size:11.5px;line-height:1.6;margin-top:8px;height:74px;overflow:hidden;color:var(--imut)"><div>✓ lu IslandLayout.swift</div><div>✓ modifié 3 fichiers</div><div style="color:var(--ifg)">› xcodebuild test</div></div><div class="row mut" style="position:absolute;bottom:14px;left:32px;font-size:12px;gap:16px"><span data-go="ouverte" class="row" style="gap:6px"><span class="keycap">⌘.</span>Arrêter</span><span class="row" style="gap:6px"><span class="keycap">T</span>Terminal</span></div></div>`};
 case"termine":return{w:520,h:200,html:`<div style="padding:0 12px" data-auto="replie:6000"><div class="row" style="justify-content:space-between">${eb("Terminé · 6 min","#9CCB8F")}${Y(44,"heureux","done","","celebrer")}</div><div class="serif" style="font-size:28px;line-height:1.1">142 tests sur 142.</div><div class="mut" style="font-size:12.5px;margin-top:4px">refonte-ile est prêt à être relu.</div><div class="row" style="gap:18px;margin-top:14px;font-size:13px"><span class="row" style="gap:6px" data-toast="Terminal ouvert"><span class="keycap">↵</span>Terminal</span><span class="row" style="gap:6px"><span class="keycap">D</span>Diff</span></div></div>`};
 case"personnage":return{w:600,h:240,html:charPanel("C",120)};
 }};
DIRS.C.ph=s=>{
 const tabs=`<div class="row" style="gap:18px;font-size:15px;margin:4px 0 6px">${[["aujourdhui","Maintenant"],["agenda","Plus tard"],["approbations","Demandes"]].map(([k,n])=>`<span data-go="${k}" style="${k===s?"text-decoration:underline;text-underline-offset:6px;text-decoration-color:#F2B36B":"color:var(--pmut)"}">${n}</span>`).join("")}<span data-go="reglages" style="margin-left:auto;color:var(--pmut)">${ic("more",18)}</span></div>`;
 const cmd=`<div style="position:absolute;left:16px;right:16px;bottom:30px;border-top:1px solid rgba(237,231,220,.16);padding-top:12px" class="row"><span data-go="conversation">${Y(26)}</span><input data-cmd placeholder="Écris à Yumi, ou /commande" style="flex:1;font:400 16px var(--serif);color:var(--pfg)">${ic("mic",18)}</div>`;
 const H=t=>`<div class="serif" style="font-size:38px;line-height:1.05;margin:6px 0 8px">${t}</div>`;
 const row=(h,t,sub,c)=>`<div class="row" style="padding:13px 0;border-bottom:1px solid rgba(237,231,220,.12);align-items:flex-start"><span class="serif tnum" style="font-size:20px;min-width:62px">${h}</span><div class="grow"><div style="font-size:15px">${t}</div>${sub?`<div class="mut" style="font-size:12.5px;color:${c||""}">${sub}</div>`:""}</div></div>`;
 const swipe=(t,sub)=>`<div class="swipe" data-swipe-right="aujourdhui" data-swipe-left="aujourdhui" style="border-bottom:1px solid rgba(237,231,220,.12);background:var(--pbg)"><div class="bgl">Autoriser</div><div class="bgr">Refuser</div><div class="fg" style="padding:13px 0;background:#0A0A09"><div class="row"><span class="serif" style="font-size:20px;min-width:62px;color:#F2B36B">!</span><div class="grow"><div class="mono" style="font-size:13.5px">${t}</div><div class="mut" style="font-size:12.5px">${sub}</div></div></div></div></div>`;
 let b="";
 switch(s){
 case"aujourdhui":b=H("Lundi")+tabs+swipe(CMD,"Claude Code · ← refuser · autoriser →")+row("14:30","Point design","dans 18 min · rejoindre","#F2B36B")+row("04:12","refonte-ile travaille","xcodebuild test")+row("12°","Paris, éclaircies","")+row("✓","Relire la PR #33","fait à 11:02");b+=`<div class="mut" style="font-size:11.5px;margin-top:10px">Balaie la demande, ou touche une ligne.</div>`+cmd;break;
 case"conversation":b=H("Yumi")+`<div style="font-size:12px" class="mut">Toi —</div><div class="serif" style="font-size:17px">Il reste quoi sur la refonte ?</div><div class="mut row" style="font-size:12px;margin-top:14px">${Y(18)} Yumi —</div><div class="serif" style="font-size:19px;line-height:1.35">Les tests passent. Il manque les réglages et la relecture de la PR #33.</div><div class="mono mut" style="font-size:12px;margin-top:8px">→ /relire 33 sur le Mac ?</div>`+cmd;break;
 case"approbations":b=H("Demandes")+tabs+swipe(CMD,"Claude Code · il y a 1 min")+swipe("rm -rf build/","Claude Code · il y a 3 min")+`<div class="mut" style="font-size:12px;margin-top:12px">→ autoriser · ← refuser · appui long : toujours</div>`;break;
 case"agenda":b=H("Plus tard")+tabs+row("14:30","Point design","Meet")+row("16:00","Focus · refonte","")+row("18:30","Sport","")+`<div class="eb mut" style="margin:18px 0 4px">Rappels</div>`+row("—","Envoyer la facture client","")+row("—","Acheter du matcha","")+cmd;break;
 case"modules":b=H("Index")+MODS.map(m=>row(m.v,m.n,m.s)).join("")+`<div class="mut" style="font-size:11px;margin-top:8px"><span class="tag">Proposition</span> écran absent de l'app iPhone actuelle</div>`;break;
 case"reglages":b=H("Réglages")+[["Mac","MacBook Pro","liaison"],["Yumi","café, voix douce","personnage"],["Mémoire","23 souvenirs",""],["Notifications","demandes seulement",""],["Agenda","autorisé",""]].map(([a,z,g])=>`<div ${g?`data-go="${g}"`:""} class="row" style="padding:14px 0;border-bottom:1px solid rgba(237,231,220,.12)"><span class="serif" style="font-size:19px" >${a}</span><span class="mut" style="margin-left:auto">${z}</span></div>`).join("");break;
 case"personnage":b=H("Yumi")+`<div style="text-align:center;margin:12px 0">${Y(140,"neutre","calm","siffle")}</div>`+charPanel("C",0).replace(/<div style="flex:none">.*?<\/div>/,"");break;
 case"liaison":b=H("Ton Mac")+`<div class="serif" style="font-size:19px;line-height:1.4;margin:10px 0 20px">Ouvre Yumi sur le Mac, tape <span class="mono" style="font-size:15px">/iphone</span>, puis scanne le code qui s'affiche.</div><div style="text-align:center">${Y(70,"curieux")}</div><div class="row" style="margin-top:20px;gap:8px;font-size:14px"><span class="keycap">↵</span><span data-go="aujourdhui" style="text-decoration:underline;text-underline-offset:4px">Scanner</span></div>`;break;}
 return b;};

/* ---------------------------------------------------------------- D */
DIRS.D={name:"Halo",style:"Midnight Aurora",
 pitch:"Yumi est au centre et les modules s'ouvrent en éventail autour de lui quand on le survole. La couleur de l'état remplit toute l'île d'une aurore : on comprend la situation avant de lire.",
 model:[["Navigation","Survoler ou toucher Yumi déploie les modules en arc. Sur iPhone, un orbe central ouvre un menu radial."],["Boutons","Deux grands halos colorés (rouge, vert) de part et d'autre, pas de capsules."],["Approbation","Les halos s'allument autour de Yumi ; l'aurore passe à l'ambre."],["Chat","Un anneau lumineux autour du champ, les réponses apparaissent au-dessus de Yumi."],["iPhone","Pas de barre d'onglets. Un orbe en bas, l'écran d'accueil est un grand « moment » sur l'aurore, avec des anneaux de progression."]],
 pro:["Prolonge la palette de Yumi sans toucher au personnage.","L'état se lit de loin, sans texte.","Navigation originale et mémorable."],con:["Menu radial moins efficace qu'une liste à 10 modules.","Peut fatiguer si l'aurore est trop présente.","Plus de travail d'animation."]};
const aur=(a,b,c)=>`<div class="aura" style="width:260px;height:150px;left:-50px;bottom:-70px;background:${a}"></div><div class="aura" style="width:240px;height:150px;right:-40px;bottom:-80px;background:${c};animation-delay:-5s"></div><div class="aura" style="width:200px;height:130px;left:40%;bottom:-90px;background:${b};animation-delay:-8s"></div>`;
const radial=(R=78,n=6,open=false,ctr="")=>`<div class="radial ${open?"open":""}" style="width:${R*2+40}px;height:${R*2+40}px">${MODS.slice(0,n).map((m,i)=>{const a=-Math.PI/2+(i-(n-1)/2)*(Math.PI*1.4/(n-1)),x=Math.cos(a)*R,y=Math.sin(a)*R;return `<span class="orb" data-go="navigation" style="--x:${x.toFixed(0)}px;--y:${y.toFixed(0)}px;background:${m.c}26;color:${m.c};box-shadow:0 0 16px ${m.c}66,inset 0 0 0 1px ${m.c}88" title="${m.n}">${ic(m.i,15)}</span>`}).join("")}<div style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)">${ctr}</div></div>`;
const halo=(c,i,go,l)=>`<div data-go="${go}" style="display:flex;flex-direction:column;align-items:center;gap:6px"><span style="width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,${c}55,${c}10 70%);box-shadow:0 0 30px ${c}88,inset 0 0 0 1.5px ${c}">${ic(i,22,"#fff",2.4)}</span><span style="font-size:11px;color:var(--imut)">${l}</span></div>`;
DIRS.D.mac=s=>{
 switch(s){
 case"replie":return{w:320,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:12px;top:4px">${Y(24)}</div><svg style="position:absolute;right:12px;top:7px" width="18" height="18" viewBox="0 0 20 20"><circle cx="10" cy="10" r="8" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="2.5"/><circle cx="10" cy="10" r="8" fill="none" stroke="#C77DFF" stroke-width="2.5" stroke-dasharray="50" stroke-dashoffset="18" transform="rotate(-90 10 10)"/></svg><div style="position:absolute;left:30px;right:30px;bottom:0;height:2px;background:linear-gradient(90deg,#5B8CFF,#C77DFF,#F58AD9);filter:blur(1px)"></div></div>`};
 case"ouverte":return{w:580,h:236,html:aur("#5B8CFF","#C77DFF","#F58AD9")+`<div class="row" style="gap:20px;position:relative"><div style="margin:-14px -10px -30px -20px">${radial(76,6,false,Y(66,"neutre"))}</div><div class="grow">${eb("Le moment","#C77DFF")}<div style="font:700 30px/1.05 var(--round);margin-top:6px">Point design</div><div class="mut" style="margin-top:2px">14:30 · dans 18 min</div><div class="row" style="margin-top:14px;gap:16px">${halo("#FF8A7A","cal","replie","Rejoindre")}${halo("#8B6CFF","chat","chat","Parler")}</div></div></div><div class="mut" style="position:absolute;bottom:10px;left:26px;font-size:11px">Survole Yumi pour ouvrir les modules</div>`};
 case"modules":return{w:600,h:270,html:aur("#5B8CFF","#C77DFF","#F58AD9")+`<div style="display:flex;justify-content:center;margin-top:-30px">${`<div class="radial open" style="width:420px;height:280px">${MODS.map((m,i)=>{const a=-Math.PI+(i/(MODS.length-1))*Math.PI,x=Math.cos(a)*170,y=Math.sin(a)*-1*-110+40;return `<span class="orb" data-go="navigation" style="--x:${x.toFixed(0)}px;--y:${(-Math.abs(Math.sin(a))*120+50).toFixed(0)}px;width:auto;height:auto;margin:-24px -30px;padding:6px 8px;border-radius:16px;background:${m.c}1e;box-shadow:inset 0 0 0 1px ${m.c}66;display:flex;flex-direction:column;align-items:center;color:${m.c}">${ic(m.i,15)}<b class="tnum" style="color:#fff;font-size:12px">${m.v}</b></span>`}).join("")}<div style="position:absolute;left:50%;top:62%;transform:translate(-50%,-50%)">${Y(76,"curieux")}</div></div>`}</div>`};
 case"chat":return{w:560,h:236,html:aur("#5B8CFF","#C77DFF","#8B6CFF")+`<div style="text-align:center;position:relative"><div style="display:inline-block;padding:7px 13px;border-radius:16px;background:rgba(140,120,255,.14);font-size:13px">48 fichiers trouvés. Je range les PDF dans Documents <span class="pulse">…</span></div><div style="margin:8px 0 6px">${Y(52,"concentre","think")}</div><div style="margin:0 auto;width:400px;height:42px;border-radius:21px;display:flex;align-items:center;padding:0 16px;font-size:13px;color:var(--imut);box-shadow:0 0 0 1.5px #C77DFF,0 0 24px #C77DFF66">Range mes téléchargements par type</div></div>`};
 case"approbation":return{w:560,h:236,html:aur("#FF9A3D","#FFB547","#FF9A3D")+`<div style="position:relative;text-align:center">${eb("Claude Code veut lancer","#FFD37A")}<div class="mono" style="font-size:14px;margin-top:4px">${CMD}</div><div class="mut" style="font-size:12px;margin-top:2px">${WHY}</div><div class="row" style="justify-content:center;gap:34px;margin-top:12px">${halo("#FF4D5E","x","ouverte","Refuser")}${Y(64,"surpris","warn")}${halo("#22C98A","ok","session","Autoriser")}</div><div class="mut" style="font-size:11px;margin-top:2px">Toujours autoriser</div></div>`};
 case"session":return{w:520,h:216,html:aur("#3F7BFF","#4FA0FF","#7FD0FF")+`<div class="row" style="gap:20px;position:relative"><div style="position:relative;width:120px;height:120px;display:grid;place-items:center"><svg style="position:absolute;inset:0" viewBox="0 0 120 120"><circle cx="60" cy="60" r="54" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="4"/><circle cx="60" cy="60" r="54" fill="none" stroke="#4FA0FF" stroke-width="4" stroke-linecap="round" stroke-dasharray="339" stroke-dashoffset="120" transform="rotate(-90 60 60)" style="filter:drop-shadow(0 0 6px #4FA0FF)"/></svg>${Y(66,"concentre","work","cafe")}</div><div class="grow">${eb("refonte-ile","#7FD0FF")}<div class="tnum" data-timer="252" style="font:700 36px/1 var(--round);margin-top:4px">04:12</div><div class="mono mut" style="font-size:12px;margin-top:6px">xcodebuild test</div></div>${halo("#FF4D5E","stop","ouverte","Arrêter")}</div>`};
 case"termine":return{w:500,h:200,html:aur("#22C98A","#3DDC97","#9BF0C8")+`<div class="row" style="gap:20px;position:relative" data-auto="replie:6000">${Y(76,"heureux","done","","celebrer")}<div class="grow">${eb("Terminé","#9BF0C8")}<div style="font:700 28px/1.1 var(--round);margin-top:4px">142 / 142</div><div class="mut">tests passés · 6 min</div></div>${halo("#22C98A","term","replie","Terminal")}</div>`};
 case"personnage":return{w:600,h:240,html:charPanel("D",120)};
 case"navigation":return{w:560,h:236,html:aur("#FF6FA8","#C77DFF","#5B8CFF")+`<div class="row" style="gap:16px;position:relative"><div style="margin:-14px -10px -30px -20px">${radial(76,6,true,Y(62,"heureux","joy","casque"))}</div><div class="grow">${eb("Musique","#FF6FA8")}<div style="font:700 30px var(--round)">Says</div><div class="mut">Nils Frahm</div><div class="line" style="margin-top:10px"><i style="background:#FF6FA8"></i></div><div class="row" style="gap:12px;margin-top:12px">${ic("prev",18)}<span style="width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:#FF6FA833;box-shadow:0 0 18px #FF6FA8aa">${ic("pause",16)}</span>${ic("next",18)}</div></div></div>`};
 }};
DIRS.D.ph=s=>{
 const orb=`<div class="scrim dmenu" data-toggle=".dmenu"></div><div class="dmenu pop" style="left:0;right:0;bottom:60px;display:flex;justify-content:center;transform-origin:bottom center">${`<div class="radial open" style="width:240px;height:180px">${[["aujourdhui","sun","#FFB86B"],["conversation","chat","#C77DFF"],["approbations","bell","#FF9A3D"],["agenda","cal","#FF8A7A"],["modules","grid","#5B8CFF"],["reglages","gear","#A09EC2"]].map(([k,i,c],n)=>{const a=Math.PI+(n/5)*Math.PI;return `<span class="orb" data-go="${k}" style="--x:${(Math.cos(a)*100).toFixed(0)}px;--y:${(Math.sin(a)*100+40).toFixed(0)}px;width:46px;height:46px;margin:-23px;background:${c}30;box-shadow:0 0 18px ${c}88,inset 0 0 0 1px ${c};color:#fff">${ic(i,19)}</span>`}).join("")}</div>`}</div><div data-toggle=".dmenu" style="position:absolute;left:50%;bottom:24px;transform:translateX(-50%);width:66px;height:66px;border-radius:50%;background:#000;display:grid;place-items:center;box-shadow:0 0 0 1px rgba(199,125,255,.4),0 0 30px #C77DFF88;z-index:26">${Y(46)}</div>`;
 const ringc=(p,c,l,v)=>`<div style="flex:0 0 96px;text-align:center"><svg width="80" height="80" viewBox="0 0 80 80"><circle cx="40" cy="40" r="34" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="6"/><circle cx="40" cy="40" r="34" fill="none" stroke="${c}" stroke-width="6" stroke-linecap="round" stroke-dasharray="214" stroke-dashoffset="${214*(1-p)}" transform="rotate(-90 40 40)" style="filter:drop-shadow(0 0 6px ${c})"/><text x="40" y="45" text-anchor="middle" fill="#fff" font-size="14" font-weight="700" font-family="ui-rounded">${v}</text></svg><div class="mut" style="font-size:11px">${l}</div></div>`;
 const T=t=>`<div style="font:800 30px/1.1 var(--round);margin:8px 0 14px">${t}</div>`;
 const bg=(a,b)=>`<div style="position:absolute;inset:-46px 0 auto 0;height:330px;overflow:hidden;pointer-events:none"><div class="aura" style="width:220px;height:200px;left:-60px;top:-40px;background:${a}"></div><div class="aura" style="width:220px;height:200px;right:-60px;top:20px;background:${b};animation-delay:-6s"></div></div>`;
 let b="";
 switch(s){
 case"aujourdhui":b=bg("#5B8CFF","#C77DFF")+`<div style="position:relative">${eb("Le moment","#C77DFF")}<div style="font:800 40px/1 var(--round);margin-top:10px">Point design</div><div class="mut" style="margin:6px 0 16px">14:30 · dans 18 min · Meet</div><div class="row" style="gap:20px">${halo("#FF8A7A","cal","agenda","Rejoindre")}${halo("#8B6CFF","chat","conversation","Demander")}</div><div class="eb mut" style="margin:26px 0 8px">En cours</div><div style="display:flex;overflow-x:auto;scrollbar-width:none;gap:4px">${ringc(.62,"#4FA0FF","refonte-ile","04:12")}${ringc(.25,"#F2B36B","Focus","18:42")}${ringc(.8,"#FF6FA8","Says","3:02")}${ringc(.4,"#3DDC97","Rappels","2/5")}</div><div data-go="approbations" style="margin-top:16px;padding:14px;border-radius:22px;background:#FF9A3D18;box-shadow:inset 0 0 0 1px #FF9A3D66,0 0 24px #FF9A3D33" class="row"><span style="color:#FFB547">${ic("bell",18)}</span><div class="grow"><b>1 demande</b><div class="mut mono" style="font-size:12px">${CMD}</div></div>${ic("right",15)}</div></div>`;break;
 case"conversation":b=bg("#8B6CFF","#5B8CFF")+`<div style="position:relative;text-align:center;margin-top:30px">${Y(90,"curieux","think")}<div style="margin:14px 6px;font:600 18px/1.35 var(--round)">Les tests passent. Il manque les réglages et la relecture de la PR #33.</div><div class="mut" style="font-size:13px">Tu as demandé : « il reste quoi sur la refonte ? »</div></div><div style="position:absolute;left:18px;right:18px;bottom:110px;height:46px;border-radius:23px;display:flex;align-items:center;padding:0 16px;color:var(--pmut);box-shadow:0 0 0 1.5px #C77DFF,0 0 24px #C77DFF55">Demande à Yumi…</div>`;break;
 case"approbations":b=bg("#FF9A3D","#FFB547")+`<div style="position:relative;text-align:center;margin-top:20px">${eb("Claude Code · 1 sur 2","#FFD37A")}<div class="mono" style="font-size:16px;margin:10px 0 6px">${CMD}</div><div class="mut" style="font-size:13px;margin:0 10px">${WHY}</div><div style="margin:20px 0">${Y(96,"surpris","warn")}</div><div class="row" style="justify-content:space-around">${halo("#FF4D5E","x","aujourdhui","Refuser")}${halo("#22C98A","ok","aujourdhui","Autoriser")}</div><div class="mut" style="font-size:12px;margin-top:10px">Toujours autoriser</div></div>`;break;
 case"agenda":b=bg("#FF8A7A","#C77DFF")+`<div style="position:relative">${T("Agenda")}${[["09:30","Stand-up","#8B9CFF",1],["14:30","Point design","#FF8A7A",0],["16:00","Focus · refonte","#F2B36B",0],["18:30","Sport","#3DDC97",0]].map(([h,t,c,past])=>`<div class="row" style="padding:12px 14px;margin-bottom:8px;border-radius:20px;opacity:${past?.45:1};${t==="Point design"?`background:${c}1c;box-shadow:inset 0 0 0 1px ${c}77,0 0 26px ${c}33`:""}"><span style="width:12px;height:12px;border-radius:50%;background:${c};box-shadow:0 0 10px ${c}"></span><b class="tnum">${h}</b><span>${t}</span></div>`).join("")}</div>`;break;
 case"modules":b=T("Modules")+`<div style="display:flex;flex-wrap:wrap;justify-content:center">${MODS.map((m,i)=>ringc([.62,.5,.8,.25,.4,.9,.3,.6,.7,.5][i],m.c,m.n,m.v.length>5?"":m.v)).join("")}</div><div class="mut" style="font-size:11px"><span class="tag">Proposition</span> écran absent de l'app iPhone actuelle</div>`;break;
 case"reglages":b=T("Réglages")+[["Mac relié","MacBook Pro","liaison","#5B8CFF"],["Yumi","café","personnage","#C77DFF"],["Mémoire","23 souvenirs","","#4EE6B0"],["Voix","douce","","#F58AD9"],["Notifications","demandes","","#FFB86B"]].map(([a,z,g,c])=>`<div ${g?`data-go="${g}"`:""} class="row" style="padding:14px;margin-bottom:8px;border-radius:20px;background:rgba(140,120,255,.07)"><span style="width:10px;height:10px;border-radius:50%;background:${c};box-shadow:0 0 10px ${c}"></span><span class="grow">${a}</span><span class="mut">${z}</span></div>`).join("");break;
 case"personnage":b=bg("#C77DFF","#F58AD9")+`<div style="position:relative">${T("Yumi")}<div style="text-align:center">${Y(140,"heureux","joy","casque")}</div>${charPanel("D",0).replace(/<div style="flex:none">.*?<\/div>/,"")}</div>`;break;
 case"liaison":b=bg("#5B8CFF","#C77DFF")+`<div style="position:relative;text-align:center;margin-top:30px">${T("Relier ton Mac")}<div class="row" style="justify-content:center;gap:14px;margin:18px 0">${ic("phone",40)}<span class="pulse" style="width:60px;height:2px;background:linear-gradient(90deg,#5B8CFF,#F58AD9);box-shadow:0 0 10px #C77DFF"></span>${ic("laptop",48)}</div>${Y(70,"curieux")}<div class="mut" style="margin:12px 10px 20px">Sur le Mac : touche Yumi › iPhone, puis scanne.</div>${halo("#C77DFF","qr","aujourdhui","Scanner")}</div>`;break;}
 return b+orb;};

