DIRS.E={name:"Atelier pro",style:"Native macOS Pro",
 pitch:"L'île devient un petit outil natif : une barre latérale à gauche, le détail à droite, des raccourcis partout. Fait pour voir plusieurs agents à la fois et agir vite, sans décor.",
 model:[["Navigation","Barre latérale avec compteurs, ⌘1 à ⌘9, recherche ⌘K."],["Boutons","Boutons système compacts (rectangle arrondi 6 pt), menu ⋯ pour les options."],["Approbation","Fiche détaillée (outil, dossier, risque) ; ⌘↩ autoriser, ⎋ refuser, ⋯ pour « toujours » ou « pour cette session »."],["Chat","Liste des conversations à gauche, fil à droite."],["iPhone","App iOS standard : grands titres, listes groupées, balayage pour autoriser, menu contextuel, barre d'onglets système."]],
 pro:["Densité maximale, plusieurs sessions d'un coup.","Le plus familier : zéro apprentissage.","Le plus simple à coder en SwiftUI natif."],con:["Peu de place pour la personnalité de Yumi.","Ressemble à un panneau de réglages.","Peu photogénique."]};
const ebtn=(l,main,go,c="#0A84FF")=>`<button ${go?`data-go="${go}"`:""} style="height:24px;padding:0 10px;border-radius:6px;font-size:12px;${main?`background:${c};color:#fff`:"background:#3A3A3C;color:#ECECEE"}">${l}</button>`;
DIRS.E.mac=s=>{
 const side=(cur)=>`<div style="width:170px;flex:none;border-right:.5px solid rgba(255,255,255,.1);padding-right:8px;font-size:12px"><div class="row" style="height:24px;padding:0 6px;border-radius:6px;background:#1C1C1E;color:var(--imut);margin-bottom:6px">${ic("search",12)}<span>Rechercher</span><span class="mono" style="margin-left:auto;font-size:10px">⌘K</span></div>${[["approbation","bell","Demandes","1","#FF9F0A"],["session","term","Agents","2","#8B9CFF"],["ouverte","cal","Agenda","3","#FF8A7A"],["navigation","music","Musique","",""],["chat","chat","Chat","",""],["modules","grid","Tous","10",""]].map(([k,i,n,c,col],x)=>`<div data-go="${k}" class="row" style="gap:7px;height:24px;padding:0 6px;border-radius:6px;${k===cur?"background:#0A84FF;color:#fff":""}">${ic(i,13,k===cur?"#fff":(col||"#8E8E93"))}<span class="grow">${n}</span>${c?`<span class="mono" style="font-size:10.5px;opacity:.75">${c}</span>`:`<span class="mono" style="font-size:10px;opacity:.5">⌘${x+1}</span>`}</div>`).join("")}</div>`;
 const wrap=(cur,detail,h=236)=>({w:640,h,html:`<div class="row" style="align-items:stretch;gap:12px;height:100%;margin:-4px -6px">${side(cur)}<div class="grow" style="position:relative">${detail}</div></div>`});
 const kv=(k,v,c)=>`<div class="row" style="font-size:12px;height:20px"><span class="mut" style="width:70px">${k}</span><span style="color:${c||"inherit"}" class="ell">${v}</span></div>`;
 switch(s){
 case"replie":return{w:360,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:10px;top:5px">${Y(22)}</div><div class="row mono" style="position:absolute;right:12px;top:8px;font-size:11px;gap:10px"><span style="color:#FF9F0A">● 1</span><span style="color:#8B9CFF">◆ 2</span><span>14:30</span></div></div>`};
 case"ouverte":return wrap("ouverte",`<div class="row" style="justify-content:space-between"><b style="font-size:13px">Agenda · aujourd'hui</b>${Y(26)}</div>${[["09:30","Stand-up","passé"],["14:30","Point design","dans 18 min"],["16:00","Focus · refonte",""],["18:30","Sport",""]].map(([h,t,n],i)=>`<div class="row" style="height:28px;font-size:12px;border-bottom:.5px solid rgba(255,255,255,.08);${i===0?"opacity:.45":""}"><span class="mono tnum" style="width:42px">${h}</span><span class="grow">${t}</span><span class="mut">${n}</span>${i===1?ebtn("Rejoindre",1,"replie"):""}</div>`).join("")}`);
 case"modules":return wrap("modules",`<table style="width:100%;border-collapse:collapse;font-size:11.5px">${MODS.map(m=>`<tr style="height:19px"><td style="width:18px;color:${m.c}">${ic(m.i,12)}</td><td>${m.n}</td><td class="mut ell" style="max-width:150px">${m.s}</td><td class="mono tnum" style="text-align:right">${m.v}</td></tr>`).join("")}</table>`,250);
 case"chat":return wrap("chat",`<div class="row" style="align-items:stretch;gap:10px;height:100%"><div style="width:120px;font-size:11.5px">${["Téléchargements","PR #33","Mail facture"].map((t,i)=>`<div style="padding:4px 6px;border-radius:5px;${i?"":"background:#2C2C2E"}"><div class="ell">${t}</div><div class="mut" style="font-size:10px">${["maintenant","10:12","hier"][i]}</div></div>`).join("")}</div><div class="grow col" style="gap:6px;font-size:12px"><div style="align-self:flex-end;background:#0A84FF;color:#fff;padding:5px 10px;border-radius:12px">Range mes téléchargements par type</div><div class="row" style="align-items:flex-start;gap:6px">${Y(20,"concentre","work")}<span class="caret">48 fichiers trouvés, je trie les PDF</span></div><div class="mono mut" style="font-size:11px">▸ mv 12 PDF ~/Documents · 3/5</div><div style="margin-top:auto;height:26px;border-radius:6px;background:#1C1C1E;display:flex;align-items:center;padding:0 8px;color:var(--imut)">Message · ⌘↩ envoyer</div></div></div>`);
 case"approbation":return wrap("approbation",`<div class="row" style="justify-content:space-between"><b style="font-size:13px;color:#FF9F0A">Demande d'autorisation</b>${Y(28,"surpris","warn")}</div><div style="margin-top:4px">${kv("Agent","Claude Code · Opus")}${kv("Outil","Bash")}${kv("Commande",`<span class="mono">${CMD}</span>`)}${kv("Dossier","~/github/Yumi")}${kv("Risque","Élevé · réseau, difficile à annuler","#FF9F0A")}</div><div class="row" style="position:absolute;right:0;bottom:0;gap:6px"><span style="position:relative"><button data-toggle=".epop" style="height:24px;width:28px;border-radius:6px;background:#3A3A3C">${ic("more",14)}</button><div class="pop epop" style="right:0;bottom:30px;width:210px;background:#2C2C2E;border-radius:8px;padding:4px;font-size:12px;box-shadow:0 10px 30px rgba(0,0,0,.5)">${["Toujours autoriser git push","Autoriser pour cette session","Copier la commande","Ouvrir le terminal"].map(t=>`<div style="padding:4px 8px;border-radius:5px" onmouseover="this.style.background='#0A84FF'" onmouseout="this.style.background=''">${t}</div>`).join("")}</div></span>${ebtn("Refuser ⎋",0,"ouverte")}${ebtn("Autoriser ⌘↩",1,"session")}</div>`);
 case"session":return wrap("session",`<table style="width:100%;border-collapse:collapse;font-size:11.5px"><tr class="mut" style="height:20px;font-size:10.5px"><td>Session</td><td>État</td><td>Outil</td><td style="text-align:right">Durée</td><td></td></tr>${[["refonte-ile","#0A84FF","travaille","xcodebuild test","04:12"],["site","#30D158","terminé","—","12:48"],["notion-risque","#FF9F0A","attend","Bash","01:03"]].map(([n,c,e,t,d],i)=>`<tr style="height:26px;border-top:.5px solid rgba(255,255,255,.08);${i?"":"background:#1C1C1E"}"><td><b>${n}</b></td><td><span style="color:${c}">●</span> ${e}</td><td class="mono mut">${t}</td><td class="mono tnum" style="text-align:right" ${i?"":'data-timer="252"'}>${d}</td><td style="text-align:right">${i===2?ebtn("Voir",1,"approbation","#FF9F0A"):ebtn("Arrêter",0,"ouverte")}</td></tr>`).join("")}</table><div class="row" style="margin-top:8px">${Y(30,"concentre","work","cafe")}<div class="mono mut" style="font-size:11px">› Test Suite 'YumiTests' started<br>› 138/142 passed…</div></div>`);
 case"termine":return wrap("session",`<div class="row" style="padding:8px 10px;border-radius:8px;background:#30D15822;box-shadow:inset 0 0 0 .5px #30D158">${chk(22)}<div class="grow" style="font-size:12.5px"><b>refonte-ile terminé</b> · 142/142 tests · 6 min</div>${ebtn("Diff",0)}${ebtn("Terminal",1,null,"#30D158")}</div><div class="row" style="margin-top:12px" data-auto="replie:6000">${Y(54,"heureux","done","soleil","celebrer")}<div class="mut" style="font-size:12px">3 fichiers modifiés · aucune erreur · aucun avertissement</div></div>`,200);
 case"personnage":return{w:620,h:240,html:charPanel("E",110)};
 case"navigation":return wrap("navigation",`<div class="row">${Y(40,"heureux","joy","casque")}<div class="grow"><b style="font-size:14px">Says</b><div class="mut" style="font-size:12px">Nils Frahm · Spotify</div></div></div><div class="row mono" style="font-size:10.5px;margin-top:10px;gap:8px"><span>1:12</span><div class="line grow"><i style="background:#FF6FA8"></i></div><span>3:02</span></div><div class="row" style="gap:6px;margin-top:10px">${ebtn(ic("prev",11),0)}${ebtn(ic("pause",11)+" ␣",1)}${ebtn(ic("next",11),0)}<span class="mut" style="font-size:11px;margin-left:auto">⌘1–6 pour changer de module</span></div>`);
 }};
DIRS.E.ph=s=>{
 const tabs=[["aujourdhui","sun","Aujourd'hui"],["conversation","chat","Parler"],["approbations","bell","Demandes"],["reglages","gear","Réglages"]];
 const cur={agenda:"aujourdhui",modules:"aujourdhui",personnage:"reglages",liaison:"reglages"}[s]||s;
 const tb=`<div style="position:absolute;left:0;right:0;bottom:0;height:80px;background:rgba(20,20,22,.94);border-top:.5px solid #38383A;display:flex;justify-content:space-around;padding-top:8px;z-index:15">${tabs.map(([k,i,n])=>`<span data-go="${k}" style="display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10px;color:${k===cur?"#0A84FF":"#8E8E93"};position:relative">${ic(i,22)}${n}${k==="approbations"?`<i style="position:absolute;top:-4px;right:6px;min-width:16px;height:16px;border-radius:8px;background:#FF453A;color:#fff;font:600 10px/16px var(--sf);font-style:normal;text-align:center">2</i>`:""}</span>`).join("")}</div>`;
 const T=(t,back)=>`${back?`<div data-go="${back}" style="color:#0A84FF;font-size:15px;margin:2px 0">‹ Réglages</div>`:""}<div style="font:700 31px/1.1 var(--sfd);margin:6px 0 10px">${t}</div>`;
 const grp=(rows,h)=>`${h?`<div class="mut" style="font-size:12px;text-transform:uppercase;margin:16px 4px 6px">${h}</div>`:""}<div style="border-radius:12px;overflow:hidden;background:#1C1C1E">${rows.join('<div style="height:.5px;background:#38383A;margin-left:52px"></div>')}</div>`;
 const r=(i,c,t,v,go,sub)=>`<div ${go?`data-go="${go}"`:""} class="row" style="padding:10px 12px;font-size:15px;background:#1C1C1E"><span style="width:28px;height:28px;border-radius:7px;background:${c};display:grid;place-items:center">${ic(i,15,"#fff",2)}</span><div class="grow"><div class="ell">${t}</div>${sub?`<div class="mut ell" style="font-size:12px">${sub}</div>`:""}</div><span class="mut">${v||""} ›</span></div>`;
 const sw=(cm,sub)=>`<div class="swipe" data-swipe-right="aujourdhui" data-swipe-left="aujourdhui"><div class="bgl">${ic("ok",16,"#fff",2.6)} Autoriser</div><div class="bgr">Refuser ${ic("x",16,"#fff",2.6)}</div><div class="fg" style="background:#1C1C1E">${r("bell","#FF9F0A",`<span class="mono" style="font-size:13.5px">${cm}</span>`,"","",sub)}</div></div>`;
 const search=`<div class="row" style="height:36px;border-radius:10px;background:#1C1C1E;padding:0 10px;color:#8E8E93;margin-bottom:6px">${ic("search",15)} Rechercher</div>`;
 let b="";
 switch(s){
 case"aujourdhui":b=T("Aujourd'hui")+search+grp([sw(CMD,"Claude Code · balaie →")],"Demandes")+grp([r("cal","#FF8A7A","Point design","14:30","agenda","dans 18 min"),r("term","#5E5CE6","refonte-ile","04:12","","xcodebuild test"),r("music","#FF2D55","Says","","","Nils Frahm")],"En cours")+grp([r("ok","#30D158","Relire la PR #33","","",""),r("ok","#8E8E93","Facture client","","","")],"Rappels");break;
 case"conversation":b=`<div class="row" style="justify-content:center;padding:4px 0 10px;border-bottom:.5px solid #38383A;margin:0 -16px 12px">${Y(26)}<b>Yumi</b></div><div class="col" style="gap:6px;font-size:15px"><div style="align-self:flex-end;background:#0A84FF;color:#fff;padding:8px 12px;border-radius:18px;max-width:78%">Il reste quoi sur la refonte ?</div><div style="background:#262628;padding:8px 12px;border-radius:18px;max-width:82%">Les tests passent. Il manque les réglages et la relecture de la PR #33.</div><div class="mut" style="font-size:11px;text-align:center">Appui long sur un message : copier, épingler, demander au Mac</div></div><div class="row" style="position:absolute;left:12px;right:12px;bottom:92px;gap:8px"><span style="width:34px;height:34px;border-radius:50%;background:#262628;display:grid;place-items:center">${ic("plus",17)}</span><div class="grow" style="height:36px;border-radius:18px;border:1px solid #38383A;display:flex;align-items:center;padding:0 12px;color:#8E8E93">iMessage-like</div></div>`;break;
 case"approbations":b=T("Demandes")+`<div class="mut" style="font-size:12.5px;margin:-4px 4px 8px">Balaie à droite pour autoriser, à gauche pour refuser.</div>`+grp([sw(CMD,"il y a 1 min · Bash · risque élevé"),sw("rm -rf build/","il y a 3 min · régénérable")],"En attente")+grp([r("ok","#30D158","npm test","","","autorisé seul · lecture et tests")],"Historique");break;
 case"agenda":b=`<div data-go="aujourdhui" style="color:#0A84FF;font-size:15px">‹ Aujourd'hui</div>`+T("Agenda")+`<div style="display:flex;background:#1C1C1E;border-radius:9px;padding:2px;margin-bottom:6px">${["Jour","Semaine","Rappels"].map((t,i)=>`<span style="flex:1;text-align:center;font-size:13px;padding:5px;border-radius:7px;${i?"":"background:#636366"}">${t}</span>`).join("")}</div>`+grp([r("cal","#5E5CE6","Stand-up","09:30"),r("cal","#FF8A7A","Point design","14:30","","Meet · dans 18 min"),r("cal","#FF9F0A","Focus · refonte","16:00"),r("cal","#30D158","Sport","18:30")]);break;
 case"modules":b=T("Modules")+grp(MODS.map(m=>r(m.i,m.c==="#E6E6E6"||m.c==="#C9D1D9"?"#48484A":m.c,m.n,m.v,"",m.s)))+`<div class="mut" style="font-size:11px;margin-top:8px"><span class="tag">Proposition</span> écran absent de l'app iPhone actuelle</div>`;break;
 case"reglages":b=T("Réglages")+grp([r("laptop","#0A84FF","Mac relié","MacBook Pro","liaison")])+grp([r("user","#5E5CE6","Yumi","Café","personnage"),r("mic","#FF9F0A","Voix","Douce"),r("mem","#30D158","Mémoire","23")],"Personnage")+grp([r("bell","#FF453A","Notifications","Demandes"),r("cal","#FF3B30","Agenda et rappels","")],"Accès");break;
 case"personnage":b=T("Yumi","reglages")+`<div style="background:#1C1C1E;border-radius:12px;padding:16px;text-align:center">${Y(110,"neutre","calm","cafe")}</div>`+grp(["Café","Cigarette","Matcha","Aléatoire"].map((t,i)=>`<div class="row" style="padding:11px 12px;font-size:15px;background:#1C1C1E"><span class="grow">${t}</span>${i?"":`<span style="color:#0A84FF">${ic("ok",17)}</span>`}</div>`),"Ce qu'il tient quand un agent travaille")+`<div style="margin-top:10px">${charPanel("E",0).replace(/<div style="flex:none">.*?<\/div>/,"")}</div>`;break;
 case"liaison":b=T("Mac relié","reglages")+grp([r("laptop","#0A84FF","MacBook Pro","Connecté","","même réseau · synchro il y a 2 min")])+grp([r("qr","#5E5CE6","Relier un autre Mac","","","scanner le code du Mac"),r("x","#FF453A","Délier","","","")]);break;}
 return b+tb;};

