DIRS.F={name:"Conversation",style:"Future Companion",
 pitch:"On ne navigue pas : on parle avec Yumi. Il annonce ce qui se passe dans une bulle et propose des réponses toutes faites. Chaque action est une réponse dans la conversation.",
 model:[["Navigation","Pas de menu : des suggestions (« Mon agenda », « Les agents »…) et la saisie libre."],["Boutons","Des réponses en bulles sous la phrase de Yumi, comme dans Messages."],["Approbation","Yumi pose la question ; on répond « Oui, vas-y », « Non » ou « Toujours pour git push ». « Pourquoi ? » déplie l'explication."],["Chat","C'est l'interface entière : l'île ouverte est la conversation."],["iPhone","L'accueil est un fil avec Yumi ; agenda, demandes et musique arrivent comme des messages interactifs."]],
 pro:["Le plus chaleureux et le plus « compagnon ».","Aucune navigation à apprendre.","Met en valeur le personnage sans le modifier."],con:["Plus lent pour consulter un chiffre précis.","Le fil peut devenir long : il faut le résumer.","Dépend de textes bien écrits pour chaque état."]};
const bub=(t,me)=>`<div style="align-self:${me?"flex-end":"flex-start"};max-width:80%;padding:8px 13px;border-radius:${me?"18px 18px 5px 18px":"18px 18px 18px 5px"};font-size:13.5px;line-height:1.35;${me?"background:#9D8BFF;color:#fff":"background:rgba(255,255,255,.08)"};animation:at-in .4s both">${t}</div>`;
const rep=(t,go,c)=>`<button ${go?`data-go="${go}"`:""} style="height:30px;padding:0 13px;border-radius:15px;font-size:12.5px;font-weight:600;box-shadow:inset 0 0 0 1.5px ${c||"#9D8BFF"};color:${c||"#CFC6FF"};white-space:nowrap">${t}</button>`;
DIRS.F.mac=s=>{
 const say=(m,r,t,reps,sc="",p="")=>`<div class="row" style="align-items:flex-end;gap:12px">${Y(62,m,r,sc,p)}<div class="grow col" style="gap:8px">${bub(t)}<div class="row" style="gap:6px;flex-wrap:wrap">${reps}</div></div></div>`;
 switch(s){
 case"replie":return{w:300,h:32,fold:1,html:`<div data-go="ouverte" style="position:absolute;inset:0"><div style="position:absolute;left:12px;top:4px">${Y(24,"curieux")}</div></div>`,below:`<div data-go="ouverte" style="margin:38px 0 0 -40px;padding:6px 12px;border-radius:14px 14px 14px 4px;background:#000;color:#fff;font:600 12px var(--round);box-shadow:0 6px 20px rgba(0,0,0,.4);animation:at-in .5s .4s both;white-space:nowrap">Point design dans 18 min</div>`};
 case"ouverte":return{w:560,h:190,html:say("heureux","calm","Ton point design commence dans 18 min. Je t'ouvre Meet ?",rep("Oui, ouvre Meet","replie")+rep("Dans 5 min",null)+rep("Et mes agents ?","session","#8B9CFF")+rep("Tout voir","modules","#A9A5C8"))};
 case"modules":return{w:600,h:250,html:`<div class="col" style="gap:8px">${`<div class="row" style="gap:10px">${Y(36,"curieux")}${bub("Voilà où on en est :")}</div>`}<div style="display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding-left:46px">${MODS.map(m=>`<div data-go="navigation" style="flex:0 0 104px;padding:10px;border-radius:18px;background:rgba(255,255,255,.06)"><span style="color:${m.c}">${ic(m.i,16)}</span><div class="tnum" style="font:800 18px var(--round);margin-top:4px">${m.v}</div><div class="mut" style="font-size:11px">${m.n}</div></div>`).join("")}</div><div class="row" style="gap:6px;padding-left:46px">${rep("Résume-moi la journée",null)}${rep("Que des urgences",null)}</div></div>`};
 case"chat":return{w:560,h:236,html:`<div class="col" style="gap:8px">${bub("Range mes téléchargements par type",1)}<div class="row" style="align-items:flex-end;gap:10px">${Y(36,"concentre","work")}<div class="col" style="gap:6px">${bub('<span class="caret">48 fichiers. Je mets les PDF dans Documents, les images dans Images</span>')}<div class="mono mut" style="font-size:11px">↳ 12 PDF → ~/Documents · 3/5</div></div></div></div><div class="row" style="position:absolute;left:20px;right:20px;bottom:14px;height:36px;border-radius:18px;background:rgba(255,255,255,.07);padding:0 6px 0 14px;font-size:13px;color:var(--imut)">Réponds à Yumi…<span style="margin-left:auto;width:28px;height:28px;border-radius:50%;background:#9D8BFF;display:grid;place-items:center">${ic("arrow",14,"#fff",2.4)}</span></div>`};
 case"approbation":return{w:580,h:236,html:say("surpris","warn",`Claude Code veut pousser 3 commits sur <b>main</b>. Je le laisse faire ?<div class="mono" style="font-size:12px;margin-top:6px;color:#FFE3B0">${CMD}</div><div class="fwhy" style="display:none;font-size:12px;margin-top:6px;color:var(--imut)">${WHY}</div>`,rep("Oui, vas-y","session","#5EF2C0")+rep("Non","ouverte","#FF8A8A")+rep("Toujours pour git push",null,"#FFC266")+`<button data-reveal=".fwhy" style="height:30px;padding:0 13px;border-radius:15px;font-size:12.5px;color:var(--imut)">Pourquoi ?</button>`)};
 case"session":return{w:560,h:200,html:say("concentre","work",`Je surveille refonte-ile. Les tests tournent depuis <b class="tnum" data-timer="252">04:12</b>.`,rep("Préviens-moi à la fin",null)+rep("Arrête tout","ouverte","#FF8A8A")+rep("Montre le terminal",null,"#A9A5C8"),"clope")};
 case"termine":return{w:540,h:190,html:`<div data-auto="replie:7000">${say("heureux","done","C'est fini ! Les 142 tests passent, en 6 minutes. Tu veux relire ?",rep("Montre le diff",null,"#5EF2C0")+rep("Merci Yumi","replie"),"","celebrer")}</div>`};
 case"personnage":return{w:600,h:240,html:charPanel("F",120)};
 case"navigation":return{w:560,h:236,html:`<div class="col" style="gap:8px">${bub("Mets de la musique",1)}<div class="row" style="align-items:flex-end;gap:10px">${Y(44,"heureux","joy","casque")}<div style="padding:10px;border-radius:18px;background:rgba(255,255,255,.07);width:260px"><div class="row"><div style="width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#FF6FA8,#8B6CFF)"></div><div><b>Says</b><div class="mut" style="font-size:12px">Nils Frahm</div></div>${ic("pause",18)}</div></div></div><div class="row" style="gap:6px;padding-left:54px">${rep("Suivant",null)}${rep("Plus calme",null)}${rep("Mon agenda","ouverte","#FF8A7A")}${rep("Les agents","session","#8B9CFF")}</div></div>`};
 }};
DIRS.F.ph=s=>{
 const head=`<div class="row" style="justify-content:space-between;margin-bottom:10px"><div class="row" data-go="personnage">${Y(32)}<div><b>Yumi</b><div style="font-size:11px;color:#5EF2C0">● Mac relié</div></div></div><span data-go="reglages" class="mut">${ic("gear",20)}</span></div>`;
 const comp=(sug)=>`<div style="position:absolute;left:12px;right:12px;bottom:26px;z-index:10"><div class="row" style="gap:6px;overflow-x:auto;scrollbar-width:none;margin-bottom:8px">${sug.map(([t,g,c])=>rep(t,g,c)).join("")}</div><div class="row" style="height:44px;border-radius:22px;background:rgba(255,255,255,.08);padding:0 6px 0 16px;color:var(--pmut)">Écris à Yumi…<span style="margin-left:auto;width:34px;height:34px;border-radius:50%;background:#9D8BFF;display:grid;place-items:center">${ic("mic",17,"#fff")}</span></div></div>`;
 const card=(inner,c)=>`<div style="padding:12px;border-radius:20px;background:rgba(255,255,255,.06);${c?`box-shadow:inset 0 0 0 1px ${c}55`:""};animation:at-in .4s both">${inner}</div>`;
 const col=x=>`<div class="col" style="gap:8px">${x}</div>`;
 const std=[["Mon agenda","agenda","#FF8A7A"],["Les demandes","approbations","#FFC266"],["Tout voir","modules","#A9A5C8"]];
 let b="";
 switch(s){
 case"aujourdhui":b=head+col(`<div class="mut" style="text-align:center;font-size:11px">Aujourd'hui 08:02</div>${bub("Bonjour ! Grosse journée : un point design à 14:30 et Claude Code bosse sur la refonte.")}${card(`<div class="row"><span style="color:#FF8A7A">${ic("cal",18)}</span><div class="grow"><b class="tnum">14:30 Point design</b><div class="mut" style="font-size:12px">dans 18 min</div></div></div>`,"#FF8A7A")}${bub("Claude Code attend ton accord pour <span class='mono' style='font-size:12px'>git push</span>.")}<div class="row" style="gap:6px">${rep("Oui","approbations","#5EF2C0")}${rep("Non",null,"#FF8A8A")}${rep("Pourquoi ?",null,"#A9A5C8")}</div>`)+comp(std);break;
 case"conversation":b=head+col(bub("Il reste quoi sur la refonte ?",1)+bub("Les tests passent. Il manque les réglages et la relecture de la PR #33. Je lance la relecture sur le Mac ?")+`<div class="row" style="gap:6px">${rep("Oui, vas-y",null,"#5EF2C0")}${rep("Plus tard",null)}</div>`)+comp([["Résume ma journée",null],["Range mes téléchargements",null]]);break;
 case"approbations":b=head+col(bub("Deux demandes t'attendent :")+card(`<div class="eb" style="color:#FFC266">Claude Code</div><div class="mono" style="font-size:13px;margin:4px 0">${CMD}</div><div class="mut" style="font-size:12px;margin-bottom:10px">${WHY}</div><div class="row" style="gap:6px">${rep("Oui","aujourdhui","#5EF2C0")}${rep("Non","aujourdhui","#FF8A8A")}${rep("Toujours",null,"#FFC266")}</div>`,"#FFC266")+card(`<div class="mono" style="font-size:13px">rm -rf build/</div><div class="mut" style="font-size:12px;margin:4px 0 10px">Supprime le build, régénérable.</div><div class="row" style="gap:6px">${rep("Oui",null,"#5EF2C0")}${rep("Non",null,"#FF8A8A")}</div>`))+comp(std);break;
 case"agenda":b=head+col(bub("Mon agenda",1)+bub("Voilà ta journée :")+card([["09:30","Stand-up"],["14:30","Point design"],["16:00","Focus · refonte"],["18:30","Sport"]].map(([h,t])=>`<div class="row" style="padding:5px 0"><b class="tnum" style="width:48px">${h}</b>${t}</div>`).join(""))+bub("Et 2 rappels : la facture client et le matcha.")+`<div class="row" style="gap:6px">${rep("Ajoute un rappel",null)}${rep("Décale le sport",null)}</div>`)+comp(std);break;
 case"modules":b=head+col(bub("Tout voir",1)+`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${MODS.slice(0,8).map(m=>card(`<span style="color:${m.c}">${ic(m.i,16)}</span><div style="font:800 18px var(--round)" class="tnum">${m.v}</div><div class="mut" style="font-size:11px">${m.n}</div>`)).join("")}</div><div class="mut" style="font-size:11px"><span class="tag">Proposition</span> vue absente de l'app iPhone actuelle</div>`)+comp(std);break;
 case"reglages":b=head+col(bub("Qu'est-ce que tu veux changer ?")+`<div class="row" style="gap:6px;flex-wrap:wrap">${rep("Ma voix",null)}${rep("Ce que je tiens","personnage")}${rep("Mes souvenirs",null)}${rep("Le Mac relié","liaison")}${rep("Les notifications",null)}</div>`+card(`<div class="row"><span>${ic("mem",18)}</span><div class="grow"><b>Mémoire</b><div class="mut" style="font-size:12px">23 souvenirs · tu peux m'en faire oublier</div></div></div>`));break;
 case"personnage":b=head+`<div style="text-align:center;margin:10px 0">${Y(140,"heureux","calm","cafe")}</div>`+col(bub("Quand un agent travaille, je prends quoi ?")+`<div class="row" style="gap:6px;flex-wrap:wrap">${["Café","Cigarette","Matcha","Surprends-moi"].map((t,i)=>`<span data-scene="${["cafe","clope","cafe",""][i]}">${rep(t,null)}</span>`).join("")}</div>`)+`<div style="margin-top:10px">${charPanel("F",0).replace(/<div style="flex:none">.*?<\/div>/,"")}</div>`;break;
 case"liaison":b=head+col(bub("On relie ton Mac ? Ouvre-moi sur le Mac, touche iPhone, puis montre-moi le code.")+card(`<div class="row" style="justify-content:center;gap:14px;padding:10px">${ic("phone",36)}<span class="pulse">• • •</span>${ic("laptop",44)}</div>`)+`<div class="row" style="gap:6px">${rep("Scanner le code","aujourdhui","#5EF2C0")}${rep("Plus tard",null)}</div>`);break;}
 return b;};

/* ================= framework ================= */
const ORDER=["A","B","C","D","E","F"];
function macHTML(dir,state){const r=DIRS[dir].mac(state);const rad=r.fold?"0 0 14px 14px":"0 0 30px 30px";
 return `<div class="mac"><div class="menubar"><div class="l"><b>Xcode</b><span>Fichier</span><span>Édition</span><span>Affichage</span><span>Produit</span></div><div class="r">${ic("bolt",13)}${ic("search",13)}<b>lun. 23 nov. 14:12</b></div></div>
 ${r.free!==undefined?`<div class="free">${r.free}</div>`:`<div class="island ${r.fold?"folded":""}" style="width:${r.w}px;height:${r.h}px;border-radius:${rad}"><div class="body">${r.html}</div></div>`}<div class="notch"></div><div class="below">${r.below||""}</div><div class="wallnote">Île à l'échelle 1 · notch 186 × 32 pt</div></div>`;}
function phHTML(dir,state){return `<div class="phonewrap"><div class="phone"><div class="scr"><div class="dyn"></div><div class="sbar"><span>14:12</span><span>●●● ▮</span></div><div class="pc">${DIRS[dir].ph(state)}</div><div class="homebar"></div></div></div></div>`;}
const frameHTML=(dir,dev,state)=>`<div class="frame d${dir}" data-dir="${dir}" data-dev="${dev}" data-state="${state}">${dev==="mac"?macHTML(dir,state):phHTML(dir,state)}</div>`;
function go(f,state){
 const dir=f.dataset.dir,dev=f.dataset.dev;f.dataset.state=state;
 if(dev==="mac"&&DIRS[dir].free){f.querySelector(".free").innerHTML=DIRS[dir].mac(state).free;}
 else if(dev==="mac"){const r=DIRS[dir].mac(state),isl=f.querySelector(".island");
  isl.style.width=r.w+"px";isl.style.height=r.h+"px";isl.style.borderRadius=r.fold?"0 0 14px 14px":"0 0 30px 30px";isl.classList.toggle("folded",!!r.fold);
  isl.innerHTML=`<div class="body">${r.html}</div>`;f.querySelector(".below").innerHTML=r.below||"";}
 else f.querySelector(".pc").outerHTML=`<div class="pc">${DIRS[dir].ph(state)}</div>`;
 mount(f);
 if(f.dataset.sync){st[f.dataset.sync]=state;save();document.querySelectorAll(`.chips [data-k]`).forEach(b=>b.setAttribute("aria-pressed",b.dataset.k===state))}}
function mount(root){
 for(let i=LIVE.length-1;i>=0;i--) if(!document.body.contains(LIVE[i].el)) LIVE.splice(i,1);
 root.querySelectorAll(".ys:not([data-on])").forEach(s=>{s.dataset.on=1;const sz=+s.dataset.s;if(!sz){s.remove();return}
  s.innerHTML=yumi({size:sz,mood:s.dataset.m,rim:s.dataset.r||"calm",rimW:sz<30?3.2:2.6});const svg=s.firstElementChild;const b=new Blob(svg);
  if(s.dataset.sc) b.setScene(s.dataset.sc);
  if(s.dataset.p) setTimeout(()=>playPose(svg,s.dataset.p),450);});
 root.querySelectorAll("[data-timer]").forEach(t=>{let v=+t.dataset.timer;clearInterval(t._i);t._i=setInterval(()=>{if(!document.body.contains(t))return clearInterval(t._i);v++;t.textContent=String(Math.floor(v/60)).padStart(2,"0")+":"+String(v%60).padStart(2,"0")},1000)});
 root.querySelectorAll("[data-stream]").forEach(t=>{const L=["  Test Case 'IslandLayoutTests' passed","  Test Case 'ModuleLineupTests' passed","  Test Case 'AgentRequestReaderTests' passed","› 138/142 passed","› 142/142 passed"];let k=0;clearInterval(t._i);t._i=setInterval(()=>{if(!document.body.contains(t))return clearInterval(t._i);const d=document.createElement("div");d.textContent=L[k++%L.length];t.appendChild(d);if(t.children.length>4)t.firstElementChild.remove()},900)});
 root.querySelectorAll("[data-auto]").forEach(a=>{const [to,ms]=a.dataset.auto.split(":"),f=a.closest(".frame"),was=f.dataset.state;setTimeout(()=>{if(document.body.contains(a)&&f.dataset.state===was)go(f,to)},+ms)});}
function toast(t){const e=document.getElementById("toast");e.textContent=t;e.classList.add("on");clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove("on"),1600)}

/* interactions */
document.addEventListener("click",e=>{
 const f=e.target.closest(".frame");
 const t=e.target.closest("[data-go],[data-page],[data-seg],[data-toggle],[data-toast],[data-scene],[data-pose],[data-mood],[data-reveal]");
 if(!t||!f) return;
 if(t.dataset.toggle!==undefined){f.querySelectorAll(t.dataset.toggle).forEach(x=>x.classList.toggle("open"));return}
 if(t.dataset.reveal){f.querySelectorAll(t.dataset.reveal).forEach(x=>x.style.display="block");return}
 if(t.dataset.toast){toast(t.dataset.toast);return}
 const yu=f.querySelector(".yumi");
 if(t.dataset.scene!==undefined&&yu&&yu._blob){yu._blob.setScene(t.dataset.scene||null);return}
 if(t.dataset.pose&&yu){playPose(yu,t.dataset.pose);return}
 if(t.dataset.mood&&yu){if(yu._blob)yu._blob.setScene(null);setMood(yu,t.dataset.mood,"calm");return}
 if(t.dataset.page!==undefined){const pg=t.closest(".body,.pc")||f;const tr=pg.querySelector(".track");if(!tr)return;const n=tr.children.length;let i=+tr.dataset.i;
  i=t.dataset.page==="+1"?(i+1)%n:t.dataset.page==="-1"?(i-1+n)%n:+t.dataset.page;tr.dataset.i=i;tr.style.transform=`translateX(-${i*100}%)`;pg.querySelectorAll(".dots i").forEach((d,k)=>d.classList.toggle("on",k===i));return}
 if(t.dataset.seg!==undefined){const k=+t.dataset.seg,box=t.closest(".body,.pc");box.querySelectorAll("[data-seg]").forEach((x,j)=>{const on=j===k;x.style.background=on?"rgba(255,255,255,.92)":"";x.style.color=on?"#0B1020":"rgba(255,255,255,.8)";const l=x.querySelector(".lbl");if(l)l.style.display=on?"":"none"});box.querySelectorAll(".pane").forEach(p=>p.classList.toggle("on",+p.dataset.pane===k));mount(box);return}
 if(t.dataset.go){const o=f.querySelector(".scrim.open");f.querySelectorAll(".open").forEach(x=>x.classList.remove("open"));go(f,t.dataset.go)}});
/* hold to confirm */
let holdT;
document.addEventListener("pointerdown",e=>{
 const h=e.target.closest("[data-hold]");
 if(h){h.classList.add("holding");const t=parseFloat(getComputedStyle(h).getPropertyValue("--holdt"))||1;holdT=setTimeout(()=>{h.classList.remove("holding");toast("Confirmé");go(h.closest(".frame"),h.dataset.hold)},t*1000);return}
 const k=e.target.closest(".slider .knob");
 if(k){const sl=k.parentElement,max=sl.clientWidth-k.offsetWidth-8,x0=e.clientX;k.classList.remove("back");k.setPointerCapture(e.pointerId);
  const mv=ev=>{const dx=Math.max(0,Math.min(max,ev.clientX-x0));k.style.transform=`translateX(${dx}px)`;k._dx=dx};
  const up=()=>{k.removeEventListener("pointermove",mv);k.removeEventListener("pointerup",up);if((k._dx||0)>max*.85){toast("Autorisé");go(sl.closest(".frame"),sl.dataset.slide)}else{k.classList.add("back");k.style.transform="";k._dx=0}};
  k.addEventListener("pointermove",mv);k.addEventListener("pointerup",up);return}
 const fg=e.target.closest(".swipe>.fg");
 if(fg){const sw=fg.parentElement,x0=e.clientX;fg.classList.remove("back");fg.setPointerCapture(e.pointerId);
  const mv=ev=>{fg._dx=ev.clientX-x0;fg.style.transform=`translateX(${fg._dx}px)`;sw.querySelector(".bgl").style.opacity=fg._dx>0?1:0;sw.querySelector(".bgr").style.opacity=fg._dx<0?1:0};
  const up=()=>{fg.removeEventListener("pointermove",mv);fg.removeEventListener("pointerup",up);const d=fg._dx||0;fg._dx=0;
   if(Math.abs(d)>80){fg.classList.add("back");fg.style.transform=`translateX(${d>0?110:-110}%)`;toast(d>0?"Autorisé":"Refusé");setTimeout(()=>sw.style.display="none",300)}else{fg.classList.add("back");fg.style.transform=""}};
  fg.addEventListener("pointermove",mv);fg.addEventListener("pointerup",up);}});
["pointerup","pointerleave","pointercancel"].forEach(ev=>document.addEventListener(ev,e=>{if(ev==="pointerleave"&&e.target!==document)return;clearTimeout(holdT);document.querySelectorAll(".holding").forEach(h=>h.classList.remove("holding"))},true));
/* command field filters its list; Enter runs the first visible line */
document.addEventListener("input",e=>{if(e.target.matches("[data-cmd]")){const q=e.target.value.toLowerCase().replace("/","");const L=e.target.closest(".body,.pc");L.querySelectorAll(".cmdlist [data-k]").forEach(x=>x.style.display=x.dataset.k.includes(q)?"":"none")}});
document.addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target.matches("[data-cmd]")){const L=e.target.closest(".body,.pc");const first=[...L.querySelectorAll(".cmdlist [data-k]")].find(x=>x.style.display!=="none");if(first)first.click();else go(e.target.closest(".frame"),"chat")}});

/* ================= the page ================= */
const st={view:"dir",dir:"A",dev:"mac",mac:"ouverte",ph:"aujourdhui",cmpMac:"approbation",cmpPh:"aujourdhui",likes:{}};
try{Object.assign(st,JSON.parse(localStorage.getItem("yumi-atelier-2")||"{}"))}catch(e){}
const save=()=>{try{localStorage.setItem("yumi-atelier-2",JSON.stringify(st))}catch(e){}};
function seg(id,items,key){const el=document.getElementById(id);el.innerHTML=items.map(([k,l])=>`<button aria-pressed="${st[key]===k}" data-k="${k}">${l}</button>`).join("");el.onclick=e=>{const b=e.target.closest("button");if(b){st[key]=b.dataset.k;render()}}}
const likeKey=(d,dev,s)=>`${d}|${dev}|${s}`;
const likeBtn=(d,dev,s)=>`<button class="like" data-like="${likeKey(d,dev,s)}" aria-pressed="${!!st.likes[likeKey(d,dev,s)]}">${st.likes[likeKey(d,dev,s)]?"♥ Gardé":"♡ J'aime"}</button>`;
document.addEventListener("click",e=>{const b=e.target.closest("[data-like]");if(!b)return;const k=b.dataset.like;if(st.likes[k])delete st.likes[k];else st.likes[k]=1;save();document.querySelectorAll(`[data-like="${k}"]`).forEach(x=>{x.setAttribute("aria-pressed",!!st.likes[k]);x.textContent=st.likes[k]?"♥ Gardé":"♡ J'aime"})});
function render(){
 save();
 seg("views",[["prop","★ Proposition"],["dir","Direction"],["cmp","Comparer un écran"],["seq","Démarrage et fermeture"],["mine","♥ Mes choix"],["shapes","Formes d'île · Mac"],["sys","Langage d'interaction"],["reco","Recommandation et mélange"]],"view");
 seg("dirs",ORDER.map(k=>[k,`${k} · ${DIRS[k].name}`]),"dir");
 seg("device",[["mac","Mac"],["ph","iPhone"]],"dev");
 document.getElementById("dirs").style.display=st.view==="dir"||st.view==="sys"?"flex":"none";
 document.getElementById("device").style.display=st.view==="dir"||st.view==="cmp"?"flex":"none";
 const m=document.getElementById("main"),D=DIRS[st.dir],mac=st.dev==="mac",list=mac?MAC_STATES:PH_STATES;
 LIVE.length=0;
 if(st.view==="dir"){const key=mac?"mac":"ph";
  m.innerHTML=`<div class="dirhead"><h2><span>${st.dir}</span>${D.name} <small style="font-size:14px;color:var(--fg3);font-weight:500">· ${D.style}</small></h2><p>${D.pitch}</p></div>
  <div class="chips" id="sts">${list.map(([k,l],i)=>`<button aria-pressed="${st[key]===k}" data-k="${k}">${i+1} · ${l}</button>`).join("")}</div>
  <div class="grid2"><div><div id="stage"></div><div class="row" style="justify-content:space-between;margin-top:10px"><div class="howto">Tout est cliquable : boutons, gestes (maintenir, glisser, balayer), points, Yumi. Les données sont fictives.</div><span id="likebox"></span></div></div>
  <div class="col" style="gap:14px"><div class="card"><h3>Comment on s'en sert</h3><table class="t">${D.model.map(([a,b])=>`<tr><th style="width:96px">${a}</th><td style="color:var(--fg2)">${b}</td></tr>`).join("")}</table></div><div class="card"><h3>Avantages</h3><ul class="pro">${D.pro.map(x=>`<li>${x}</li>`).join("")}</ul><h3 style="margin-top:12px">Limites</h3><ul class="con">${D.con.map(x=>`<li>${x}</li>`).join("")}</ul></div></div></div>`;
  const stage=document.getElementById("stage");
  const draw=()=>{stage.innerHTML=frameHTML(st.dir,st.dev,st[key]);stage.firstElementChild.dataset.sync=key;document.getElementById("likebox").innerHTML=likeBtn(st.dir,st.dev,st[key]);mount(stage)};
  draw();
  document.getElementById("sts").onclick=e=>{const b=e.target.closest("button");if(!b)return;st[key]=b.dataset.k;save();document.querySelectorAll("#sts button").forEach(x=>x.setAttribute("aria-pressed",x===b));draw()};}
 else if(st.view==="cmp"){const key=mac?"cmpMac":"cmpPh";
  m.innerHTML=`<div class="dirhead"><h2>Même écran, six façons de s'en servir</h2><p>Chaque cadre est un prototype vivant et indépendant : essaie les gestes dans chacun. Coche ce que tu aimes, je m'en servirai pour la proposition mélangée.</p></div>
  <div class="chips" id="sts">${list.map(([k,l])=>`<button aria-pressed="${st[key]===k}" data-k="${k}">${l}</button>`).join("")}</div>
  <div class="cmpgrid ${mac?"":"ph"}">${ORDER.map(d=>`<div class="cell"><h4><span>${d} · ${DIRS[d].name} <small>${DIRS[d].style}</small></span>${likeBtn(d,st.dev,st[key])}</h4><div class="${mac?"zoommac":"zoomph"}">${frameHTML(d,st.dev,st[key])}</div></div>`).join("")}</div>`;
  mount(m);
  document.getElementById("sts").onclick=e=>{const b=e.target.closest("button");if(!b)return;st[key]=b.dataset.k;render()};}
 else if(st.view==="sys"){
  m.innerHTML=`<div class="dirhead"><h2><span>${st.dir}</span>${D.name} · langage d'interaction</h2><p>${D.pitch}</p></div>
  <div class="grid2" style="grid-template-columns:repeat(auto-fill,minmax(min(100%,440px),1fr))">
   <div class="card"><h3>Règles</h3><table class="t">${D.model.map(([a,b])=>`<tr><th style="width:96px">${a}</th><td style="color:var(--fg2)">${b}</td></tr>`).join("")}</table></div>
   <div class="card"><h3>Le même Yumi, cadré par cette direction</h3><div class="frame d${st.dir}" data-dir="${st.dir}" data-dev="mac" style="background:var(--isl);color:var(--ifg);border-radius:24px;padding:16px;height:220px;font-family:var(--f)">${charPanel(st.dir,110)}</div><p style="font-size:12.5px">Personnage, humeurs, habitudes et poses viennent du moteur d'origine, sans modification.</p></div>
   <div class="card" style="grid-column:1/-1"><h3>Les écrans clés côte à côte</h3><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,420px),1fr));gap:12px">${["approbation","session","termine"].map(s=>`<div class="zoommac" style="zoom:.55">${frameHTML(st.dir,"mac",s)}</div>`).join("")}</div></div>
  </div>`;mount(m);}
 else if(st.view==="prop") propView();
 else if(st.view==="seq") seqView();
 else if(st.view==="mine") mineView();
 else if(st.view==="shapes") shapesView();
 else m.innerHTML=reco();}
function reco(){
 const likes=Object.keys(st.likes);
 return `<h1>Recommandation et mélange</h1><p class="lede">Rien n'est validé. Le personnage reste identique dans toutes les propositions : seule l'interface change.</p>
 <div class="grid2" style="grid-template-columns:repeat(auto-fill,minmax(min(100%,460px),1fr));margin-top:18px">
 <div class="card"><h3>Tes coups de cœur (${likes.length})</h3>${likes.length?`<table class="t">${likes.map(k=>{const [d,dev,s]=k.split("|");if(d==="Q"){const it=SEQS[dev].find(x=>x[0]===s);return `<tr><td><b>${({mac_l:"Démarrage Mac",mac_q:"Fermeture Mac",ph_l:"Lancement iPhone"})[dev]}</b></td><td>${it?it[1]:s}</td><td></td></tr>`}if(d==="S")return `<tr><td><b>Forme</b> · ${SHAPES[dev].name}</td><td>Mac</td><td>${SH_STATES.find(x=>x[0]===s)[1]}</td></tr>`;return `<tr><td><b>${d}</b> · ${DIRS[d].name}</td><td>${dev==="mac"?"Mac":"iPhone"}</td><td>${[...MAC_STATES,...PH_STATES].find(x=>x[0]===s)[1]}</td></tr>`}).join("")}</table>`:`<p>Clique « ♡ J'aime » sous un prototype ou dans la vue Comparer : la liste se remplit ici et me servira de base.</p>`}</div>
 <div class="card"><h3>Ma proposition de mélange</h3><p><b>Mac : la base E (Atelier pro) pour la structure</b>, parce que voir plusieurs agents et agir au clavier est le cœur de Yumi. On garde de A la règle « une action sensible = maintenir » pour les commandes à risque, et de D l'aurore qui prend la couleur de l'état.</p><p><b>iPhone : F (Conversation) pour l'accueil</b>, avec les demandes balayables de E/C, parce que sur le téléphone on vérifie et on répond plus qu'on ne navigue.</p><p><b>Commun</b> : la ligne de commande de C dans le chat Mac (« / » pour aller à un module).</p></div>
 <div class="card"><h3>Ce qui se combine bien</h3><table class="t"><tr><th>Élément</th><th>Source</th></tr><tr><td>Île repliée avec compteurs</td><td>E</td></tr><tr><td>Maintenir pour les actions à risque</td><td>A</td></tr><tr><td>Glisser pour autoriser (trackpad, iPhone)</td><td>B</td></tr><tr><td>Barre « / » commande et chat</td><td>C</td></tr><tr><td>Couleur d'état en aurore</td><td>D</td></tr><tr><td>Barre latérale + ⌘1…⌘9</td><td>E</td></tr><tr><td>Réponses toutes faites sous Yumi</td><td>F</td></tr><tr><td>Demandes balayables sur iPhone</td><td>C ou E</td></tr><tr><td>Menu radial depuis Yumi</td><td>D</td></tr></table></div>
 <div class="card"><h3>Réel ou proposé</h3><ul><li>Réel dans le dépôt : île repliée et ouverte, vue « Tous », chat en direct avec action en cours, approbation avec « Toujours autoriser », lecture des demandes sans risque, sessions Claude Code, 10 modules, habitudes café / cigarette / matcha, mémoire, voix, iPhone à trois onglets, liaison Mac.</li><li><span class="tag">Proposition</span> tous les gestes (maintenir, glisser, balayer, radial), 4ᵉ onglet Demandes, écran Modules sur iPhone, raccourcis ⌘, ligne de commande « / », réponses suggérées.</li></ul></div>
 </div>`;}

