const sbtn=(l,to,c,fill)=>`<button data-sgo="${to}" style="height:28px;padding:0 13px;border-radius:99px;font-size:12px;font-weight:650;white-space:nowrap;${fill?`background:${c};color:#000`:`box-shadow:inset 0 0 0 1.4px ${c||"rgba(255,255,255,.3)"};color:${c||"#fff"}`}">${l}</button>`;
const rb=(i,c,to,s=30)=>`<button data-sgo="${to}" style="width:${s}px;height:${s}px;border-radius:50%;background:${c};display:grid;place-items:center;flex:none">${ic(i,s*.48,"#fff",2.6)}</button>`;
