  survol:B("cal","#FF8A7A",120,4,"14:30 Point design","ouvert")+B("term","#8B9CFF",124,48,"refonte-ile · 04:12","agent",.05,32)+B("music","#FF6FA8",124,88,"Says · Nils Frahm","",.1,32),
