  agent:`<div class="row" style="position:absolute;left:calc(50% + 118px);top:4px;gap:8px"><span style="position:relative;width:44px;height:44px;border-radius:50%;background:#000;display:grid;place-items:center"><svg style="position:absolute;inset:0" viewBox="0 0 44 44"><circle cx="22" cy="22" r="20" fill="none" stroke="#4FA0FF" stroke-width="3" stroke-dasharray="126" stroke-dashoffset="50" stroke-linecap="round" transform="rotate(-90 22 22)"/></svg>${Y(28,"concentre","work","cafe")}</span><b style="background:#000;padding:4px 10px;border-radius:99px;font-size:12px;color:#7FD0FF">${TIMER}</b></div>`,
