 bonnet:{n:"Bonnet",head:`<path d="M17 24Q50-16 83 24Z" fill="${CO_A}"/><rect x="14" y="17" width="72" height="10" rx="5" fill="${CO_W}"/>${[19,24,29,34,39,44,49,54,59,64,69,74,79].map(x=>`<path d="M${x} 18v8" stroke="#C9CCD8" stroke-width="1"/>`).join("")}<g class="co-bob"><circle cx="50" cy="-6" r="6.5" fill="${CO_W}"/><circle cx="48" cy="-8" r="2.2" fill="#fff"/></g>`},
