document.addEventListener("mouseover",e=>{const ea=e.target.closest(".dP .pears");if(!ea)return;const f=ea.closest(".frame");if(f._opening)return;f._opening=1;const y=ea.querySelector(".yumi");if(y)playPose(y,"saut");setTimeout(()=>{f._opening=0;if(["repos","notif"].includes(f.dataset.state))go(f,"accueil")},380)});
