    <div style="${wbg};height:128px"><div style="font-size:10.5px;color:#5B8CFF;font-weight:650">Agents</div>${[["concentre","work","cafe","Yumi","04:12"],["surpris","warn","","site","attend"]].map(([m,r,sc,n,t])=>`<div class="row" style="gap:6px;margin-top:8px">${Y(22,m,r,sc)}<span class="grow" style="font-size:12px">${n}</span><span style="font-size:10.5px;color:${t==="attend"?"#FFB547":"#8E8E93"}">${t}</span></div>`).join("")}<div style="font-size:10px;color:#8E8E93;margin-top:8px">1 demande en attente</div></div>
