/* ================= Démarrage et fermeture : 5 variantes de chaque, sur le vrai Yumi ================= */
const SEQS={
 mac_l:[["l1","Le réveil","La goutte gonfle sous la notch, les yeux s'ouvrent dans le noir, la lumière s'allume, il salue, puis s'assoit dans l'oreille. (L'animation actuelle de l'app, qui finit en oreilles.)"],
  ["l2","La chute","Yumi tombe d'en haut de l'écran dans la notch, s'écrase, et les oreilles s'ouvrent sous le choc."],
  ["l3","La goutte d'encre","Une goutte noire tombe de la notch, rebondit, puis s'étale en oreilles ; Yumi sort de la goutte."],
  ["l4","Le rideau","Les oreilles s'ouvrent lentement comme un rideau ; Yumi monte dans l'oreille gauche et s'étire au réveil."],
  ["l5","Discret","Deux yeux clignent dans la notch, un trait de lumière court le long de l'île qui s'ouvre en oreilles. 1,5 s, pour tous les jours."]],
 mac_q:[["q1","L'au revoir","L'île s'ouvre, « À tout à l'heure », il salue, s'endort, s'éteint, et la goutte remonte dans la notch. (La fermeture actuelle de l'app.)"],
  ["q2","Le saut","Yumi saute de l'oreille dans la notch et disparaît ; les oreilles se rentrent derrière lui."],
  ["q3","Dodo","Il bâille et s'endort, sa lumière baisse, et l'île se referme doucement comme des paupières."],
  ["q4","Le trou noir","Un tourbillon s'ouvre dans la notch et l'aspire en spirale, puis se referme."],
  ["q5","Rapide","Un petit signe de la main et tout se replie. Moins d'une seconde."]],
 ph_l:[["p6","Le réveil + la chute","Il se réveille dans la Dynamic Island et dit bonjour, puis il tombe tout droit dans le rond du bas, pile au centre et à la bonne taille, pendant que l'app apparaît."],["p1","Le réveil","La Dynamic Island s'étire en goutte, il se réveille, « Bonjour Esteban », remonte, puis ressort en bas. (L'animation actuelle, avec la nouvelle arrivée.)"],
  ["p2","La chute","Yumi tombe de la Dynamic Island jusqu'à sa place en bas, s'écrase en atterrissant, et l'app apparaît derrière lui."],
  ["p3","La bulle","Une bulle monte du bas, éclate, Yumi apparaît au milieu et descend se poser."],
  ["p4","Le rideau","Le noir s'ouvre en deux depuis la Dynamic Island et dévoile l'app ; Yumi monte du bas."],
  ["p5","Discret","L'app apparaît en fondu, Yumi dort en bas, puis se réveille et salue."]]};
const sqYS=(box)=>box.querySelector(".yumi");
function sqMac(id){return `<div class="frame dP" data-dir="P" data-dev="mac" data-seqv="${id}"><div class="mac" style="height:300px"><div class="menubar"><div class="l"><b>Xcode</b><span>Fichier</span><span>Édition</span></div><div class="r"><b>lun. 23 nov. 14:12</b></div></div><div class="notch"></div><div class="seqbox" style="position:absolute;inset:0;z-index:5"></div></div></div>`}
function sqPhone(id){return `<div class="frame dP" data-dir="P" data-dev="ph" data-seqv="${id}"><div class="phonewrap" style="padding:10px 0;border:0"><div class="phone"><div class="scr"><div class="dyn"></div><div class="sbar"><span>14:12</span><span>●●● ▮</span></div><div class="pc" style="opacity:0"></div><div class="seqbox" style="position:absolute;inset:0;z-index:28;overflow:hidden"></div><div class="homebar"></div></div></div></div></div>`}
const EARS={w:"300px",h:"32px",r:"0 0 12px 12px"};
function sqIsl(o={}){return `<div class="sq-isl" style="position:absolute;left:50%;top:0;transform:translateX(-50%);width:${o.w||"184px"};height:${o.h||"32px"};border-radius:${o.r||"0 0 12px 12px"};background:#000;overflow:${o.ov||"visible"};transition:all ${o.t||".55s"} cubic-bezier(.32,1.22,.42,1)"><div class="sq-glow" style="position:absolute;left:50%;top:60%;width:200px;height:130px;transform:translate(-50%,-50%) scale(.3);border-radius:50%;background:radial-gradient(circle,#8B6CFF66,#F58AD922 50%,transparent 70%);opacity:0;transition:all .8s;pointer-events:none"></div><div class="sq-y" style="position:absolute;left:${o.yx||"50%"};top:${o.yy||"40px"};transform:translate(-50%,-50%) scale(${o.ys||.7});opacity:${o.yo??0};transition:all .55s cubic-bezier(.32,1.22,.42,1)">${Y(70,o.mood||"sommeil")}</div></div>`}
const css=(el,o)=>Object.assign(el.style,o);
const toEars=(isl,yw,extra={})=>{css(isl,{width:EARS.w,height:EARS.h,borderRadius:EARS.r,...extra});css(yw,{left:"22px",top:"16px",transform:"translate(-50%,-50%) scale(.34)",opacity:1})};
