function seqView(){const m=document.getElementById("main");
 const cell=(kind,[id,n,d])=>`<div class="cell"><h4><span>${n}</span><span class="row" style="gap:6px"><button class="like" data-replay>↻ Rejouer</button>${likeBtn("Q",kind,id)}</span></h4><div style="padding:0 14px 10px;color:var(--fg2);font-size:12.5px">${d}</div>${kind==="ph_l"?`<div class="zoomph">${sqPhone(id)}</div>`:sqMac(id)}</div>`;
 m.innerHTML=`<div class="dirhead"><h2>Démarrage et fermeture</h2><p>Cinq façons de démarrer Yumi sur Mac, cinq façons de le fermer, cinq façons de lancer l'app iPhone. Toutes finissent sur l'interface validée. Clique ♡ sur celles que tu préfères : je reporterai ton choix dans ★ Proposition.</p></div>
 <h2 style="font:700 20px var(--sfd);margin:22px 0 10px">Mac · démarrage</h2><div class="cmpgrid">${SEQS.mac_l.map(x=>cell("mac_l",x)).join("")}</div>
 <h2 style="font:700 20px var(--sfd);margin:30px 0 10px">Mac · fermeture</h2><div class="cmpgrid">${SEQS.mac_q.map(x=>cell("mac_q",x)).join("")}</div>
 <h2 style="font:700 20px var(--sfd);margin:30px 0 10px">iPhone · lancement de l'app</h2><div class="cmpgrid ph" style="grid-template-columns:repeat(auto-fill,minmax(250px,1fr))">${SEQS.ph_l.map(x=>cell("ph_l",x)).join("")}</div>`;
 if(window._seqIO)window._seqIO.disconnect();
 window._seqIO=new IntersectionObserver(es=>es.forEach(en=>{const f=en.target;if(en.isIntersecting&&en.intersectionRatio>.55){if(!f._played){f._played=1;runVariant(f)}}else if(!en.isIntersecting||en.intersectionRatio<.2){seqStop(f)}}),{threshold:[0,.2,.55,.8]});
 m.querySelectorAll("[data-seqv]").forEach(f=>window._seqIO.observe(f));}
function seqStop(f){if(f._seq)f._seq.forEach(clearTimeout);f._seq=null;f._played=0;const b=f.querySelector(".seqbox");if(b){b.innerHTML="";b.style.background="";b.style.opacity=""}const pc=f.querySelector(".pc");if(pc){pc.innerHTML="";pc.style.opacity=0}f.querySelectorAll(".scr > .phorb,.scr > .phfade,.scr > .phcomp,.scr > .pmenu2").forEach(x=>x.remove());for(let i=LIVE.length-1;i>=0;i--)if(!document.body.contains(LIVE[i].el))LIVE.splice(i,1)}
document.addEventListener("click",e=>{const b=e.target.closest("[data-replay]");if(b){const f=b.closest(".cell").querySelector("[data-seqv]");seqStop(f);f._played=1;runVariant(f)}});

/* étoiles filantes derrière Yumi, à la place du halo */
const STARS=(n=9)=>`<div class="sq-stars" style="position:absolute;inset:0;opacity:0;transition:opacity .6s;pointer-events:none">${Array.from({length:n},(_,i)=>`<i style="top:${(i*37+8)%85}%;left:${(i*53+20)%100}%;animation-delay:${(i*0.47)%2.6}s;animation-duration:${1.4+(i%4)*.35}s"></i>`).join("")}</div>`;
const HELLO=()=>((navigator.language||"fr").toLowerCase().startsWith("fr")?"Bonjour":"Hello")+" Esteban";
render();
